(13, '尿酸',             'UA',   'μmol/L',    15.00, '男 208-428，女 155-357', 4, '升高为高尿酸血症/痛风的诊断依据，也与心血管风险相关'),
(14, '估算肾小球滤过率', 'eGFR', 'ml/min/1.73m²', 20.00, '≥90',        4, '<60持续3个月以上可诊断慢性肾脏病(CKD)'),
