(15, '总胆固醇',         'TC',   'mmol/L',    20.00, '理想<5.18，边缘升高5.18-6.19，升高≥6.22', 5, 'ASCVD风险评估的核心指标之一'),
(16, '甘油三酯',         'TG',   'mmol/L',    20.00, '理想<1.70，边缘升高1.70-2.25，升高≥2.26', 5, '餐后波动大，需空腹采血；显著升高(≥5.6)有诱发急性胰腺炎风险'),
(17, '高密度脂蛋白胆固醇','HDL-C','mmol/L',    20.00, '男>1.00，女>1.30', 5, '"好胆固醇"，具有心血管保护作用，低值(<1.0)为危险因素'),
(18, '低密度脂蛋白胆固醇','LDL-C','mmol/L',    20.00, '理想<3.37，边缘升高3.37-4.12，升高≥4.14', 5, '"坏胆固醇"，ASCVD首要干预靶点'),
-- 血糖 (group 6)
(19, '空腹血糖',         'FBG',  'mmol/L',    12.00, '3.9-6.1',         6, '6.1-7.0为糖尿病前期(IFG)，≥7.0需复查确认糖尿病'),
(20, '糖化血红蛋白',     'HbA1c','%',          30.00, '4.0-6.0',         6, '反映近2-3个月平均血糖水平，≥6.5%为糖尿病诊断切点'),
-- 影像 (group 7)
(21, '胸部X线正位片',    'CXR',  '-',         80.00, '双肺纹理清晰，心影大小形态正常，膈面光整', 7, '筛查肺结核、肺部肿瘤、心脏扩大等'),
(22, '十二导联心电图',   'ECG',  '-',         30.00, '窦性心律，心率60-100次/分，PR间期0.12-0.20s，QRS<0.12s，QTc<440ms(男)/<460ms(女)', 7, '筛查心律失常、心肌缺血、心室肥厚等'),
(23, '腹部超声',         'US-ABD','-',        100.00,'肝、胆、胰、脾、双肾大小形态正常，回声均匀，未见明显占位性病变', 7, '需空腹8小时以上检查'),
(24, '甲状腺超声',       'US-THY','-',        100.00,'甲状腺大小形态正常，回声均匀，未见明显结节', 7, '筛查甲状腺结节、弥漫性病变'),
-- 肿瘤标志物 (group 8)
(25, '甲胎蛋白',         'AFP',   'ng/mL',    60.00, '<7.0',           8, '原发性肝癌筛查首选指标，也见于活动性肝炎、肝硬化、妊娠期'),
(26, '癌胚抗原',         'CEA',   'ng/mL',    60.00, '<5.0（非吸烟者），<10.0（吸烟者）', 8, '广谱肿瘤标志物，结直肠癌、胃癌、肺癌、胰腺癌等可升高'),
(27, '糖类抗原19-9',     'CA19-9','U/mL',     80.00, '<37.0',          8, '胰腺癌、胆道癌筛查指标，也见于胰腺炎、胆道梗阻'),
(28, '糖类抗原125',      'CA125', 'U/mL',     80.00, '<35.0',          8, '卵巢癌筛查指标，也见于子宫内膜异位症、盆腔炎、良性卵巢囊肿'),
(29, '前列腺特异性抗原', 'PSA',   'ng/mL',    80.00, '<4.0（随年龄调整：50-59岁<3.5，60-69岁<4.5，≥70岁<6.5）', 8, '前列腺癌筛查指标，也见于前列腺增生、前列腺炎'),
