(30, '骨密度T值(腰椎)',  'BMD-L', 'SD',      120.00, 'T≥-1.0正常，-2.5<T<-1.0骨量减少，T≤-2.5骨质疏松', 9, '双能X线吸收法(DXA)是金标准'),
(31, '碳13呼气试验',     'UBT',   '-',       150.00, 'DOB值<4.0‰为阴性', 9, '检测幽门螺杆菌(Hp)感染的金标准，需停用抗生素4周、PPI 2周后检查');

