INSERT INTO package_info (id, package_name, description, price, suitable_for, status) VALUES
(1, '基础体检套餐',   '血常规+尿常规+肝功能3项+肾功能3项+空腹血糖+心电图+胸部X线。共12项检测，适合年度常规健康筛查。',                                              388.00,  '18-60岁普通人群的常规年度体检，入职体检参考', 'ACTIVE'),
(2, '标准体检套餐',   '在基础套餐上增加：血脂全套6项+腹部超声+甲状腺超声+肿瘤标志物3项(AFP+CEA+CA19-9)。共20项检测，对常见慢性病及肿瘤风险进行初步筛查。',         888.00,  '35岁以上人群，有慢性病家族史或不良生活方式者', 'ACTIVE'),
(3, '尊享深度体检套餐','包含全部检测项目：血/尿常规+肝功能+肾功能+血脂全套+血糖+影像检查(4项)+肿瘤标志物(5项)+骨密度+动脉硬化检测+眼底照相+碳13呼气试验。共31项，全面深度健康评估。', 2888.00, '45岁以上人群，有较高健康风险或追求全面深度健康筛查者', 'ACTIVE'),
(4, '女性专属体检套餐', '基础套餐+乳腺及妇科超声+肿瘤标志物(CA125)+甲状腺超声+骨密度。针对女性特有的乳腺癌、宫颈癌、骨质疏松风险进行重点筛查。',                           888.00,  '25岁以上女性，特别是有乳腺/妇科疾病家族史者', 'ACTIVE'),
(5, '心脑血管专项套餐','血脂全套+空腹血糖+糖化血红蛋白+心电图+动脉硬化检测+颈部血管超声+同型半胱氨酸。针对心脑血管疾病高风险人群的深度评估。',                                 1288.00, '40岁以上及有高血压/高血脂/糖尿病/冠心病家族史者', 'ACTIVE'),
(6, '老年关爱体检套餐', '尊享套餐所有项目+眼底照相+骨密度+维生素D水平+叶酸+维生素B12。针对老年人群多系统健康问题的综合筛查与评估。',                                             2288.00, '60岁以上长者，特别是伴有多种慢性病者', 'ACTIVE');

