INSERT INTO exam_plan (id, member_id, plan_name, plan_date, package_id, status, report_path, conclusion) VALUES
(1,  1,  '赵建国2026年度体检',        '2026-03-10', 5, 'COMPLETED', '/reports/2026/exam_001_zhao.pdf',
 '1. 血压 152/94mmHg（复测 148/92mmHg），符合1级高血压标准，血压控制未达标，需调整降压方案；
2. 空腹血糖 6.5mmol/L（↑），糖化血红蛋白 6.8%（↑），提示近2-3个月血糖控制欠佳，建议内分泌科就诊调整降糖方案；
3. 总胆固醇 5.72mmol/L（↑），LDL-C 3.68mmol/L（↑），HDL-C 0.92mmol/L（↓），符合混合型高脂血症；
4. BMI 26.3kg/m²（超重），腰围 96cm（中心性肥胖）；
5. 心电图：左心室高电压（提示高血压性心脏改变可能）；
6. 尿蛋白微量（±），需复查尿微量白蛋白/肌酐比值排除早期肾损伤。'),
(2,  2,  '钱晓芳婚前体检',            '2026-04-15', 1, 'COMPLETED', '/reports/2026/exam_002_qian.pdf',
 '各项检测指标均在正常参考范围内：血常规正常、尿常规阴性、肝肾功能正常、空腹血糖4.8mmol/L、心电图窦性心律。甲状腺超声未见结节。建议：备孕前3个月开始补充叶酸0.4mg/日，完成TORCH及传染病筛查。'),
(3,  3,  '孙明伟年度体检',            '2026-05-20', 2, 'COMPLETED', '/reports/2026/exam_003_sun.pdf',
 '1. BMI 28.8kg/m²（肥胖），腰围 105cm（中心性肥胖）；
2. ALT 78U/L（↑）、AST 56U/L（↑）、GGT 128U/L（↑↑），腹部超声：中度脂肪肝（回声弥漫性增强，肝内管道显示不清）；
3. 甘油三酯 3.42mmol/L（↑↑），总胆固醇 6.15mmol/L（↑），LDL-C 4.35mmol/L（↑），HDL-C 0.85mmol/L（↓）；
4. 空腹血糖 5.8mmol/L（正常高值），尿酸 486μmol/L（↑）；
5. 血压 138/88mmHg（正常高值）；心电图正常。'),
(4,  5,  '周文博入职体检',            '2026-06-01', 1, 'COMPLETED', '/reports/2026/exam_005_zhou.pdf',
 '所有检查项目均在正常范围。BMI 22.6kg/m²，血压 118/72mmHg，空腹血糖 5.1mmol/L，血脂四项正常，肝肾功能正常，心电图窦性心律 68次/分。健康状况良好，无明显异常发现。'),
(5,  4,  '李秀英老年专项体检',        '2026-03-15', 6, 'COMPLETED', '/reports/2026/exam_004_li.pdf',
 '1. 骨密度：腰椎T值-2.1（骨量减少），股骨颈T值-1.8（骨量减少），10年主要骨质疏松性骨折风险(FRAX)为15.2%；
2. 维生素D 25-OH水平 18.2ng/mL（↓，不足）；
3. 血压 135/78mmHg（正常高值），心电图正常，血脂正常；
4. 腹部超声：肝脏小囊肿（直径约1.2cm，无需处理）；眼底检查：轻度动脉硬化改变；
5. 碳13呼气试验 DOB值 8.6‰（阳性），提示Hp现症感染，建议根除治疗。'),
(6,  6,  '吴丽华乳癌筛查专项',        '2026-06-18', 4, 'COMPLETED', '/reports/2026/exam_006_wu.pdf',
 '1. 乳腺超声：双侧乳腺增生（BI-RADS II级），未见明确占位性病变；
2. 妇科超声：子宫及双附件未见明显异常；
3. CA125 15.2U/mL（正常范围）；
4. 甲状腺超声：甲状腺右侧叶见3×2mm小结节（TI-RADS III级，建议随访）；
5. 其余血尿常规、生化检查均正常。乳房自检教育已完成。建议：40岁后每年加做乳腺钼靶检查。'),
(7,  7,  '郑国强年度体检',            '2026-07-05', 2, 'PENDING',  NULL, NULL),
(8,  8,  '王美玲婚前健康检查',        '2026-07-08', 4, 'PENDING',  NULL, NULL),
(9,  9,  '冯志强综合体检(复检)',      '2026-06-05', 3, 'COMPLETED', '/reports/2026/exam_009_feng.pdf',
 '1. BMI 32.9kg/m²（重度肥胖），腰围 112cm；
2. 血压 158/98mmHg（复测156/96mmHg，2级高血压），心电图：左心室高电压+ST-T改变；
3. 尿酸 538μmol/L（↑↑），空腹血糖 6.3mmol/L（IFG），糖化血红蛋白 6.2%（↑）；
4. 甘油三酯 4.85mmol/L（↑↑），总胆固醇 6.42mmol/L（↑），ALT 68U/L（↑）、GGT 155U/L（↑↑）；
5. 腹部超声：重度脂肪肝，肝脏增大；颈部血管超声：双侧颈动脉内膜增厚（IMT 1.2mm），右侧颈总动脉分叉处见混合性斑块（大小约8.2×2.5mm），管腔狭窄约25%；
6. 动脉硬化检测：ABI右侧0.92/左侧0.95，PWV 1680cm/s（↑↑，提示动脉僵硬度显著增加）。'),
(10, 10, '陈雪莲糖尿病筛查',          '2026-02-20', 2, 'COMPLETED', '/reports/2026/exam_010_chen.pdf',
 '1. 空腹血糖 6.8mmol/L（IFG），糖化血红蛋白 6.3%（↑，糖尿病前期），OGTT 2h血糖 10.2mmol/L（IGT）；
2. 空腹胰岛素 18.5μIU/mL（↑，提示胰岛素抵抗），HOMA-IR指数 4.6（↑）；
3. BMI 25.4kg/m²（超重），腰围 88cm（女性中心性肥胖切点≥80cm）；
4. 血压 142/86mmHg（1级高血压），总胆固醇 5.45mmol/L（↑），LDL-C 3.52mmol/L（↑）；
5. 尿微量白蛋白/肌酐比值(UACR) 38mg/g（↑，微量白蛋白尿期，提示早期糖尿病肾病可能）。'),
