-- ==============================
-- 10. 评估记录（10条，专业医学评估）
-- ==============================
INSERT INTO assessment_record (id, member_id, template_id, type, total_score, risk_level, conclusion, suggestion, assessor_id, assess_date) VALUES
(1, 1,  NULL, 'RISK', 68.50, 'MEDIUM',
 '综合评估结果：血压148/92mmHg（1级高血压未达标），空腹血糖6.5mmol/L+糖化血红蛋白6.8%（糖尿病血糖未达标），BMI 26.3超重+腰围96cm中心性肥胖，TC 5.72/LDL-C 3.68/HDL-C 0.92（混合型高脂血症），尿蛋白微量阳性，心电图左心室高电压。ASCVD 10年风险评分约6.8%（中危）。主要风险因素：高血压、2型糖尿病、血脂异常、超重、高盐饮食。',
 '1.【药物调整】建议心内科复诊，考虑CCB联合ARB强化降压，目标<140/90mmHg（若耐受可<130/80mmHg）；内分泌科评估二甲双胍剂量调整及是否需要联合SGLT-2i；
2.【饮食】严格低盐（<5g/日）、低脂、低碳水化合物饮食，每日热量控制在1800-2000kcal，增加蔬菜至500g/日；
3.【运动】每日快走30-40分钟，心率控制在100-110次/分（约最大心率的60-70%）；
4.【监测】每日早晚测血压并记录，每周测空腹及餐后2h血糖各2次；
5.【复查】1个月后复查血压、空腹血糖、尿微量白蛋白/肌酐比值；3个月后全面复查。',
 2, '2026-03-10'),

(2, 2,  NULL, 'RISK', 95.00, 'LOW',
 '综合评估结果：BMI 21.2（理想范围），血压112/68mmHg，空腹血糖4.8mmol/L，血脂四项全部正常，肝肾功能正常，心电图及影像检查无异常。各项健康指标均在理想范围内。10年ASCVD风险评分<1%（低危）。',
 '1. 保持现有健康生活方式：均衡膳食、每周≥150分钟中等强度运动；
2. 备孕建议：双方完成孕前检查（TORCH、甲状腺功能、传染病筛查），女方提前3个月开始补充叶酸0.4-0.8mg/日；
3. 工作压力管理：推荐正念冥想或瑜伽，保证每日7-8小时睡眠；
4. 每年常规体检一次即可。',
 2, '2026-04-15'),

(3, 3,  NULL, 'RISK', 52.00, 'HIGH',
 '综合评估结果：BMI 28.8（肥胖），腰围105cm（严重中心性肥胖），ALT 78/AST 56/GGT 128（肝酶显著升高），腹部超声中度脂肪肝，TG 3.42（重度高甘油三酯血症），TC 6.15/LDL-C 4.35/HDL-C 0.85（混合型高脂血症），空腹血糖5.8（正常高值），尿酸486（高尿酸血症），血压138/88（正常高值）。代谢综合征诊断成立（满足中心性肥胖+高TG+低HDL-C+血压偏高+血糖偏高5条标准）。ASCVD 10年风险约4.5%（中低危，但综合代谢状况为高危）。',
 '1.【生活方式干预（优先级最高）】严格戒酒（酒精是脂肪肝和TG升高的首要可逆因素），每日总热量控制在1600-1800kcal，低碳水化合物+高蛋白饮食（蛋白质占比25-30%），完全避免含糖饮料；
2.【运动处方】每周至少5天有氧运动（快走/游泳/骑行），每次≥45分钟，心率120-135次/分；每周2次抗阻训练（深蹲、俯卧撑等）；
3.【减重目标】6个月内减重10-12kg（减重≥7%可显著逆转脂肪肝），每月减重1.5-2kg；
4.【药物】消化内科就诊评估水飞蓟宾+维生素E治疗脂肪肝；若生活方式干预3个月后TG仍>2.3，考虑非诺贝特治疗；
5.【监测】每月查肝功能+血脂，每3个月腹部超声复查脂肪肝程度；
6.【警示】重度高TG（>5.6）有诱发急性胰腺炎风险，若TG进一步升高需紧急干预。',
 2, '2026-05-20'),

(4, 4,  NULL, 'RISK', 72.00, 'MEDIUM',
 '综合评估结果：骨密度腰椎T值-2.1/股骨颈T值-1.8（骨量减少），维生素D 18.2ng/mL（不足），BMI 24.7（正常上限），血压135/78mmHg（正常高值）。10年主要骨质疏松性骨折风险FRAX 15.2%（中危）。碳13呼气试验阳性（Hp现症感染）。眼底轻度动脉硬化。肝脏小囊肿（良性，≤2cm）。',
 '1.【骨质疏松防治】碳酸钙D3片（含元素钙600mg+维生素D 400IU）每日2次+普通维生素D 800IU/日，使总钙摄入量达1200mg/日、维生素D达1200IU/日；3个月后复查25-OH维生素D水平；
2.【运动】每周3次负重运动（快走、爬楼梯）+2次抗阻训练（弹力带、轻哑铃），每次30分钟；
3.【防跌倒】居家环境评估（移除地面障碍物、浴室安装扶手、增加夜间照明）；
4.【Hp根除】消化内科就诊，铋剂四联疗法（PPI+铋剂+阿莫西林+克拉霉素）14天，停药1个月后复查碳13呼气试验确认根除；
5.【肝脏囊肿】良性病变，直径1.2cm无恶性风险，每年超声随访即可；
6. 6个月后复查骨密度，每年1次眼底检查。',
 2, '2026-03-15'),

(5, 6,  NULL, 'RISK', 78.00, 'MEDIUM',
 '综合评估结果：乳腺增生（BI-RADS II级，良性），甲状腺右叶结节TI-RADS III级（低风险，恶性概率<5%），无占位性病变。PHQ-9评分12分（中度抑郁），GAD-7评分9分（轻度焦虑）。睡眠：入睡困难（上床后>1小时）+早醒（凌晨2-3点，醒后难再入睡）+总睡眠时间<5小时/日，为期约6个月。',
 '1.【乳腺健康】每1-2年乳腺超声随访；40岁起每年加做乳腺钼靶；
2.【甲状腺结节】6个月后复查甲状腺超声，若结节稳定则延长至每年1次；
3.【心理健康】强烈建议精神科/心理科就诊，评估是否需SSRI类药物治疗（如舍曲林或艾司西酞普兰）；配合认知行为疗法(CBT-I)改善失眠；正念减压(MBSR)每周1次×8周；
4.【运动】每日户外散步30分钟（上午为佳，利用光照调节昼夜节律），每周3次中等强度有氧运动（瑜伽、游泳等）；
5.【睡眠卫生】固定就寝/起床时间（如23:00-6:30），睡前1小时禁用电子产品，卧室仅用于睡眠，睡眠限制疗法；
6.【社会支持】鼓励与家人/朋友沟通情绪状态，参加病友支持团体；
7. 2周后复评PHQ-9/GAD-7，评估干预效果。',
 2, '2026-06-18'),

(6, 9,  NULL, 'RISK', 38.00, 'HIGH',
 '综合评估结果：BMI 32.9（重度肥胖/II级肥胖），血压158/98mmHg（2级高血压），尿酸538（显著升高），空腹血糖6.3（IFG）+HbA1c 6.2%（糖尿病前期），TG 4.85（重度高甘油三酯血症，接近急性胰腺炎风险阈值5.6），TC 6.42/LDL-C 4.52/HDL-C 0.78，ALT 68/GGT 155（酒精性+非酒精性混合肝损伤），腹部超声重度脂肪肝，颈部血管超声双侧颈动脉IMT增厚+右侧斑块形成（狭窄约25%），ABI 0.92/0.95（轻度下降）+PWV 1680cm/s（动脉僵硬度显著升高）。代谢综合征+亚临床动脉粥样硬化。ASCVD 10年风险约9.5%（中高危）。若不干预，5年内发生心脑血管事件概率较高。',
 '1.【紧急警示教育】向患者充分告知当前多重代谢紊乱的严重性和动脉粥样硬化已存在的客观事实，强调若不改变生活方式预后不良；
2.【戒酒（绝对要求）】立即完全戒酒，告知酒精是脂肪肝加重、TG升高、尿酸升高、血压升高的共同元凶；
3.【饮食重塑】严格低嘌呤饮食（禁食动物内脏、贝类海鲜、浓肉汤）+低脂（脂肪供能<25%）+低碳水化合物+低盐（<4g/日），每日总热量控制在1500-1700kcal，蛋白质以鸡胸肉、鱼虾、豆腐为主，蔬菜>600g/日，每日饮水≥2500ml；
4.【运动】从低强度开始（水中行走、坐姿踏步），每次20分钟逐渐增加至每次45分钟每周5-6天，心率控制在105-120次/分；
5.【药物（多学科联合）】
  - 降压：建议CCB(氨氯地平5mg qd)+ARB(厄贝沙坦150mg qd)联合，逐步滴定至目标<140/90mmHg（理想<130/80）；
  - 降尿酸：非布司他40mg qd（起始），目标尿酸<360μmol/L（已有动脉斑块者更严格目标<300）；
  - 降脂：阿托伐他汀20mg qn，LDL-C目标<2.6mmol/L（已有动脉斑块）；
  - 保肝：水飞蓟宾胶囊140mg tid；
  - TG极高：若生活方式+他汀后TG仍>5.6，加用非诺贝特（注意与他汀间隔12小时服用以降低肌病风险）；
6.【减重】3个月内减重5-7kg，6个月减重12-15kg（目标BMI<30，最终<28）；
7.【监测】每2周测血压/体重/腰围；每月查肝肾功能、血脂、尿酸；3个月后复查颈动脉超声+动脉硬化检测+腹部超声；
8.【戒烟】强烈建议同时戒烟（当前吸烟20支/天），推荐尼古丁替代疗法+戒烟门诊。',
 2, '2026-06-05'),

(7, 10, NULL, 'RISK', 66.00, 'MEDIUM',
 '综合评估结果：空腹血糖6.8+OGTT 2h血糖10.2（IGT合并IFG，糖尿病前期高危），HbA1c 6.3%（超目标值），HOMA-IR 4.6（显著胰岛素抵抗），BMI 25.4（超重）+腰围88cm（中心性肥胖，超过女性80cm切点），血压142/86mmHg（1级高血压），TC 5.45/LDL-C 3.52（边缘升高），UACR 38mg/g（微量白蛋白尿阳性，提示早期糖尿病肾病可能）。代谢综合征诊断成立。若不干预，5年内进展为2型糖尿病的概率约40-50%。',
 '1.【糖尿病预防（核心目标）】生活方式干预是逆转糖尿病前期的关键——严格控制碳水化合物摄入（主食每餐≤75g生米/面，优先全谷物），总热量1500-1600kcal/日，蛋白质占比20-25%，膳食纤维≥25g/日；
2.【运动】每日餐后快走20分钟（三餐后各一次最优），每周累计≥150分钟中等强度运动，增加肌肉量以改善胰岛素敏感性；
3.【体重管理】3个月内减重3-5kg（减重5-7%可降低糖尿病发生风险58%）；
4.【血压管理】低盐饮食（<5g/日），若1个月生活方式后血压仍≥140/90，启动ACEI/ARB治疗（推荐厄贝沙坦150mg qd，兼有肾脏保护作用）；
5.【血糖监测】每周测空腹+三餐后2h血糖各1天（血糖谱），每3个月复查HbA1c；
6.【肾脏保护】ACEI/ARB可降低尿蛋白，避免使用肾毒性药物（NSAIDs等），每年复查UACR+eGFR；
7.【随访】内分泌科每3个月随访1次，评估糖尿病进展情况以及是否需要启动二甲双胍治疗（二甲双胍可降低糖尿病前期进展为糖尿病的风险约31%）。',
 2, '2026-02-20'),

(8, 13, NULL, 'RISK', 68.00, 'MEDIUM',
 '综合评估结果：BMI 28.6（肥胖），TC 6.28（↑↑）+LDL-C 4.42（↑↑）+TG 2.35（↑）+HDL-C 0.90（↓），空腹血糖5.5（正常），血压132/82（正常高值），尿酸395（正常），肝肾功能正常。单纯性肥胖+重度混合型高脂血症。ASCVD 10年风险约3.8%（中低危，但LDL-C水平已达高危级别）。',
 '1.【降脂治疗（核心）】生活方式+药物治疗联合：阿托伐他汀20mg qn起始，目标LDL-C<3.37（理想<2.6），若4周后未达标增至40mg qn或联合依折麦布10mg qd；
2.【饮食】低胆固醇饮食（每日胆固醇<300mg，蛋黄每周≤3个，限制红肉及加工肉类），增加可溶性膳食纤维（燕麦、豆类、魔芋、奇亚籽等），用橄榄油/菜籽油替代猪油/黄油；
3.【运动】每周5次有氧运动（快走/慢跑/游泳），每次40-50分钟，心率120-135次/分；
4.【减重】3-4个月内减重6-8kg（目标BMI<25.5）；
5.【监测】每4周复查血脂四项+肝功能（监测他汀肝酶影响），3-4个月后评估减重和降脂效果。',
 2, '2026-05-10'),

(9, 15, NULL, 'RISK', 60.00, 'MEDIUM',
 '综合评估结果：吸烟指数900年支（吸烟45年×20支/天，属重度吸烟者），血压150/90mmHg（1级高血压），慢性咳嗽3年（晨起明显，白痰，活动后气短——高度提示慢性支气管炎/COPD可能），BMI 25.5（超重）。肺功能未做过，存在COPD筛查缺口。10年ASCVD风险约8.2%（中高危），肺癌筛查风险符合低剂量CT筛查标准（年龄≥50岁+吸烟指数≥20包年）。',
 '1.【戒烟（绝对优先）】在45年吸烟史和已出现呼吸道症状的情况下，戒烟是唯一能减慢肺功能下降速度的干预措施。推荐尼古丁替代疗法+伐尼克兰+戒烟门诊联合干预；
2.【COPD筛查】立即安排肺功能检查（FEV1/FVC比值），若<0.7确诊COPD，根据GOLD分级制定吸入治疗方案（LABA/LAMA/ICS）；
3.【肺癌筛查】低剂量螺旋CT(LDCT)，根据Lung-RADS分级制定随访计划；
4.【高血压管理】低盐饮食（<5g/日）+氨氯地平5mg qd起始，目标<140/90mmHg；
5.【呼吸道症状】戒烟后评估咳嗽变化；若咳嗽持续，需除外COPD、肺癌相关咳嗽；
6.【接种疫苗】流感疫苗每年1次+肺炎球菌疫苗(PPSV23)+重组带状疱疹疫苗；
7.【运动】在肺功能评估后制定个体化运动方案（若确诊COPD需肺康复训练）；
8.【监测】1个月内完成肺功能+LDCT检查，每月监测血压，3个月后综合评估。',
 2, '2026-04-08'),

(10, 14, NULL, 'RISK', 92.00, 'LOW',
 '综合评估结果：BMI 20.1（理想范围），血压108/66mmHg，各项实验室检查均正常。健康状况良好，适合备孕。目前补充叶酸中，生活方式健康（瑜伽爱好者，素食为主）。',
 '1.【备孕管理】继续补充叶酸0.4mg/日至孕12周；双方完成染色体核型分析及遗传病携带者筛查（若尚未完成）；
2.【营养】建议转为蛋奶素（加入鸡蛋、牛奶、酸奶），确保蛋白质≥60g/日、铁≥20mg/日、钙≥800mg/日、维生素B12≥2.4μg/日；必要时补充铁剂和维生素B12；
3.【运动】继续瑜伽练习，备孕期间避免高温瑜伽及剧烈扭转体式；加做核心肌群和盆底肌训练；
4.【疫苗接种】确认风疹、水痘、乙肝抗体状态，必要时孕前补种（减毒活疫苗需提前3个月）；
5.【检查】建议完成甲状腺功能+TORCH+阴道分泌物检查（备孕常规）。
健康的身体状况对妊娠和胎儿发育非常重要，您目前各项指标非常理想，祝备孕顺利！',
 2, '2026-07-30');

-- ==============================
-- 11. 中医体质辨识（8条，含舌脉诊详细记录）
-- ==============================
INSERT INTO tcm_constitution (id, member_id, constitution_type, score, description, health_advice) VALUES
(1, 1,  '痰湿质(兼夹气虚)', 78,
 '【主症】形体肥胖（BMI 26.3），腹部肥满松软，面部油脂较多，汗多而黏，晨起咯痰，口黏腻或甜，胸闷脘痞。
【舌脉】舌体胖大，舌质淡红，舌苔白厚腻，边有齿痕；脉滑，稍濡。
【兼夹】气虚质倾向：神疲乏力，动则气短，语声低微。
【成因】长期高盐高脂饮食，久坐少动，损伤脾胃，水湿内停，聚湿生痰。',
 '1.【饮食调养】宜清淡，多食冬瓜、薏苡仁、赤小豆、山药、白萝卜、陈皮、茯苓等健脾化痰祛湿之品；忌肥甘厚味、煎炸烧烤、甜腻食物；
2.【运动调养】每日坚持快走40分钟以上，以微微出汗为宜，可加做八段锦"两手托天理三焦""调理脾胃须单举"两式，各重复8-12次；
3.【穴位保健】艾灸足三里（双）、丰隆（双）、中脘，每穴10-15分钟，每周3次；
4.【茶饮方】陈皮6g+茯苓10g+炒薏苡仁15g，代茶饮，每日1剂。'),

(2, 2,  '平和质', 90,
 '【主症】面色红润有光泽，毛发润泽，目光有神，精力充沛，睡眠质量好（入睡快、不早醒），二便调，纳佳，情绪平和。
【舌脉】舌淡红，苔薄白；脉和缓有力，节律均匀。
【评价】先天禀赋良好，后天调养得当，阴阳气血调和，是理想的体质状态。',
 '【平和质调理重在"守"而非"变"】
1.【饮食有节】三餐定时定量，荤素搭配合理（建议荤素比3:7），不偏嗜某种口味；
2.【起居有常】保持23:00前入睡、6:30-7:00起床的规律作息；
3.【不妄作劳】保持现有运动习惯（每周2次健身房+偶尔瑜伽），避免过度劳累；
4.【情志调摄】继续实践正念冥想或瑜伽，做好工作压力管理；
5.【未病先防】每年常规体检即可，关注甲状腺功能等常规项目。备孕前转为"蛋奶素"以确保蛋白质和维生素B12摄入。'),

(3, 4,  '阴虚质(兼夹血瘀)', 72,
 '【主症】形体偏瘦，口燥咽干（夜间尤甚），手足心热，喜凉饮，大便偏干（2-3日一行，质硬），皮肤干燥瘙痒，偶有耳鸣如蝉。
【舌脉】舌体瘦小，舌质偏红，少津，苔少有裂纹；脉细数，尺脉弱。
【兼夹】血瘀质倾向：面色晦暗，唇色偏暗，皮肤可见少量老年斑。
【成因】年过七七，天癸竭，肾阴亏虚；长期家务劳作，暗耗阴血。',
 '1.【饮食滋阴】多食梨（雪梨炖冰糖）、银耳（银耳莲子羹）、百合、鸭肉、甲鱼、黑芝麻、枸杞子、桑葚；忌辛辣温燥（辣椒、花椒、羊肉、桂圆等）；
2.【药膳推荐】六味地黄丸加减食疗：枸杞15g+山药30g+熟地10g炖瘦肉汤，每周2-3次；
3.【穴位保健】按摩太溪穴（双）、三阴交（双）、涌泉（双），每穴3-5分钟，早晚各1次；勿艾灸（阴虚者忌灸）；
4.【润肠通便】晨起空腹温水300ml+蜂蜜1勺；多食火龙果、猕猴桃、西梅等润肠水果；
5.【护肤】洗澡水温不宜过高，浴后立即涂抹润肤乳（含神经酰胺成分更佳）；
6.【禁忌】避免熬夜（最晚23:00前入睡），因熬夜伤阴最为显著。'),

(4, 6,  '气郁质(兼夹血虚)', 75,
 '【主症】神情抑郁，善太息，胸胁胀满，情绪低落易哭，对事物缺乏兴趣，喉中如有异物梗阻（梅核气），乳房经前胀痛明显。
【舌脉】舌淡红，苔薄白微腻；脉弦细，左关尤弦。
【兼夹】血虚质倾向：面色萎黄不华，头晕眼花，心悸，月经量偏少色淡。
【成因】长期工作压力+情绪不舒，肝气郁结，失于疏泄；思虑过度，暗耗心血。',
 '1.【饮食调畅】多食小麦、金橘、佛手、玫瑰花、合欢花、黄花菜（萱草）、山楂等行气解郁、疏肝理气之品；忌咖啡、浓茶等兴奋性饮品（加重焦虑）；
2.【情志疏导】心理治疗+CBT疗法（已在西医干预中进行），配合中医情志相胜疗法；
3.【穴位按摩】太冲（双，行间上一寸，向行间方向推揉）+膻中（顺时针揉按）+内关（双）+神门（双），每穴3-5分钟，每日早晚各1次；
4.【运动】推荐集体性运动（羽毛球、广场舞、团体瑜伽），借助社交活动改善情绪；
5.【药茶方】玫瑰花6g+合欢花6g+红枣3枚（掰开），代茶饮，每日1剂；
6.【音乐疗法】多听角调式音乐（如《胡笳十八拍》《蓝色多瑙河》），角音入肝，疏肝解郁。'),

(5, 9,  '湿热质(兼夹痰湿)', 65,
 '【主症】形体肥胖（BMI 32.9），面垢油光，易生痤疮，口苦口干，身重困倦，小便黄赤，大便黏滞不爽（挂厕难冲），阴囊潮湿。
【舌脉】舌质红，苔黄厚腻（中后部为甚）；脉滑数有力。
【兼夹】痰湿质倾向：胸闷痰多，腹部肥满，汗黏。
【成因】长期过食肥甘厚味（火锅、烧烤）+大量饮酒+作息颠倒，湿热内生，壅滞三焦。',
 '1.【饮食清热祛湿（最为关键）】多食绿豆、冬瓜、苦瓜、薏苡仁、赤小豆、芹菜、莴苣、藕等清热利湿之品；严格控制：酒类（完全戒断）、辛辣、油炸、甜腻、海鲜发物；
2.【药膳】薏苡仁赤小豆汤：生薏苡仁30g+赤小豆30g（非红豆）+陈皮5g+茯苓15g，煮水代茶饮，每日1剂；夏季加绿豆30g同煮；
3.【运动出汗排湿】推荐高强度间歇运动（HIIT）或持续出汗的有氧运动，每次40-60分钟，每周≥5天，务必达到全身出汗的程度（汗出则湿有出路）；
4.【穴位保健】可刮痧膀胱经（背部）+拔罐（以皮肤潮红为度，勿起泡），每周1次；艾灸足三里+丰隆+阴陵泉，每穴15分钟，每周2-3次；
5.【作息调整】逐步将睡眠时间提前至24:00前，避免宵夜（夜宵加重湿热）。'),

(6, 10, '血瘀质(兼夹气虚)', 68,
 '【主症】肤色晦暗不泽，面部色素沉着（双颧部褐色斑片），口唇紫暗，皮肤干燥粗糙，下肢皮肤可见少量瘀斑，偶有心前区刺痛感（持续约1-3分钟，自行缓解）。
【舌脉】舌质暗红，可见散在瘀点，舌下络脉增粗迂曲呈紫暗色；脉细涩，重按无力。
【兼夹】气虚质倾向：神疲乏力，动则气短，语声低微，易出汗。
【成因】心气不足，推动无力，血行迟缓，滞而为瘀。久坐少动加重气滞血瘀。糖尿病前期之"脾瘅"日久亦致瘀。',
 '1.【饮食活血化瘀】多食山楂（山楂红糖水）、黑豆、黑木耳、洋葱、茄子、醋、桃仁（少量）、玫瑰花茶；忌寒凉生冷食物（寒则血凝）；
2.【药膳方】三七粉3g（早晚各1.5g温水冲服，活血不留瘀）+丹参10g+红枣5枚煮水代茶饮；若正在服用阿司匹林或其他抗凝药物需咨询医生后再服用三七；
3.【运动行气活血】每日坚持快走或慢跑30-40分钟（促进全身气血流通）+八段锦"两手攀足固肾腰"+"背后七颠百病消"，各重复8-12次；
4.【穴位保健】艾灸血海（双）+三阴交（双）+关元，每穴10-15分钟，每周3次（温经通络、活血化瘀）；
5.【情志调养】保持乐观情绪，避免忧思抑郁（气滞加重血瘀），多参与社区活动；
6.【禁忌】避免久坐久卧（久坐伤气、久卧伤肉），每小时起身活动5分钟。'),

(7, 11, '平和质(偏阴虚倾向)', 86,
 '【主症】年轻体健，面色润泽，头发稠密有光泽，精力较充沛，但近期因频繁熬夜略感口干、眼干，偶有口腔溃疡。
【舌脉】舌淡红，尖稍红，苔薄白少津；脉细稍数，左寸偏旺。
【评价】先天体质平和，但因长期熬夜（伤阴）+大量用眼（肝血暗耗），出现轻度阴虚内热倾向。若不调整，有向阴虚质转化的趋势。',
 '1.【纠正作息（最关键）】熬夜是当前体质偏颇的首因，务必逐步将入睡时间从凌晨1-2点提前至23:30前，保证7-8小时睡眠；
2.【护眼】每用电脑/手机45分钟远眺5分钟，热敷眼部每晚1次，枸杞菊花茶（枸杞15粒+菊花3朵）每日1杯；
3.【饮食】多食蓝莓、胡萝卜、猪肝（维生素A）、坚果（维生素E）；继续避免芒果、菠萝等过敏原食物；
4.【运动】保持每周健身习惯，建议增加户外运动（自然光有助于调节生物节律）；
5.【穴位】按摩睛明穴+太阳穴+风池穴（缓解眼疲劳），太溪穴（滋阴），每日3-5分钟。
坚持调整3个月后复评体质，预计可恢复平和质。'),

(8, 15, '气虚质(兼夹痰湿+血瘀)', 58,
 '【主症】形体偏胖，面色㿠白无华，神疲乏力明显，活动后气促（上二楼即需歇息），语声低怯，自汗（动则汗出），怕风易感冒，晨起咳嗽咯白痰。
【舌脉】舌质淡暗（淡主气虚、暗主血瘀），舌体胖大边有齿痕（水湿内停），舌苔白腻（痰湿）；脉沉细弱，右寸关尤弱（肺脾气虚）。
【兼夹分析】气虚为本（肺脾气虚——长期吸烟伤肺气、年老脾胃功能减退），痰湿为标（气虚水液运化失常），血瘀为变（气虚推动无力血行迟缓+吸烟导致血瘀）。
【成因】高龄+45年吸烟史+久坐少动+饮食偏咸偏油腻。',
 '1.【补气固本（核心治则）】
  - 饮食：多食黄芪炖鸡、党参山药粥、大枣小米粥、牛肉、鸡蛋等健脾补肺益气之品；
  - 药茶：黄芪15g+党参10g+陈皮5g，煮水代茶饮（晨起及午后各1杯，晚上不喝以免影响睡眠）；
  - 中成药参考：玉屏风颗粒（益气固表止汗，尤其适合表虚自汗易感冒者）+补中益气丸（补中益气升阳）；
2.【化痰】陈皮6g+茯苓15g+炒白术10g煮水代茶饮（健脾化痰），少食生冷甜腻食物以免生痰；
3.【活血】每日坚持散步30分钟（量力而行，不追求速度和强度）+八段锦全套（从简化4式开始逐渐过渡到全套8式），以行气活血；
4.【穴位保健】艾灸足三里+关元+气海+肺俞，每穴15分钟，每周3次（温补肺脾之气）；
5.【呼吸训练】缩唇呼吸+腹式呼吸，每日练习2次，每次10分钟，改善肺功能；
6.【饮食禁忌】戒烟（已在西医干预中）+忌食生冷、油腻、过咸食物。');

-- ==============================
-- 12. 心理评测（7条）
-- ==============================
INSERT INTO psychology_assessment (id, member_id, assessment_type, total_score, result_level, analysis, suggestion, assess_date) VALUES
(1, 2, 'SCL-90', 102, 'NORMAL', 'SCL-90总分102分（全国常模129.96±38.76），9个因子分均在正常范围内（<2.0）：躯体化1.18、强迫1.42、人际敏感1.23、抑郁1.20、焦虑1.15。整体心理健康状况良好。强迫因子略高于常模（可能与产品经理工作中追求细节完美相关），但远低于临床预警线2.5分。', '保持当前良好的心理状态。高压工作期间可每周1-2次正念冥想（推荐Headspace App），每次10-15分钟。如情绪波动持续超过2周可随时复评。', '2026-04-15'),
(2, 3, 'SCL-90', 168, 'MILD', 'SCL-90总分168分（明显高于全国常模）。异常因子：躯体化2.35（轻度异常）、抑郁2.12（轻度异常）、焦虑2.28（轻度异常）。结合临床访谈：(1)躯体化升高与近期体检异常结果（中度脂肪肝、高血脂）后的过度担忧有关；(2)抑郁+焦虑升高源于对健康状况恶化的恐惧；(3)存在情绪性进食倾向。', '1.认知重建：帮助患者正确理解体检结果——脂肪肝和高血脂是可逆的代谢性疾病，通过减重和生活方式改变可以显著改善；2.行为激活：制定每周运动计划，通过运动改善情绪；3.腹式呼吸训练（4-7-8呼吸法：吸气4秒→屏气7秒→呼气8秒），每日3次；4.记录情绪与进食的关联；5.4周后复查SCL-90。', '2026-05-20'),
(3, 6, 'PHQ-9+GAD-7', 12, 'MODERATE', 'PHQ-9总分12分（中度抑郁）：兴趣减退2分、情绪低落2分、睡眠障碍3分（入睡困难+凌晨2-3点易醒）、精力不足2分、自我评价低1分、注意力不集中1分。GAD-7总分9分（轻度焦虑）。核心症状：抑郁为主（中度），焦虑为辅（轻度），睡眠障碍突出。发病诱因可能与母亲乳腺癌确诊（2025年）后的心理创伤及自身乳腺癌家族史带来的健康焦虑有关。自杀意念筛查阴性（PHQ-9条目9=0分）。', '1.强烈建议精神科/心理科就诊评估SSRI类药物治疗（推荐舍曲林50mg qd起始或艾司西酞普兰10mg qd）；2.CBT-I失眠认知行为治疗：刺激控制疗法+睡眠限制疗法+放松训练；3.每周3-4次有氧运动（游泳优先，对关节压力小+改善情绪），每次30-45分钟；4.鼓励与家人坦诚沟通情绪状态；5.提供24小时心理援助热线：400-161-9995；6.2周后复测PHQ-9/GAD-7，若PHQ-9≥15分或出现自杀意念需立即精神科就诊。', '2026-06-18'),
(4, 9, 'GAD-7+PHQ-9', 14, 'MODERATE', 'GAD-7总分14分（中度焦虑，接近重度阈值15分）：紧张3分、无法停止担忧2分、担忧过多3分、坐立不安2分、易怒2分。PHQ-9总分10分（轻度抑郁）。症状模式：焦虑为主（中度），抑郁为辅（轻度）。核心发现：(1)健康焦虑突出——体检发现异常后反复上网查询（每日>2小时）；(2)灾难化思维——"我是不是快不行了"；(3)回避行为——因担心听到坏消息而推迟复查。睡眠：入睡困难（>1小时）+凌晨惊醒（心慌、出汗）。', '1.尽快精神科就诊：GAD-7接近重度应评估药物治疗（推荐舍曲林50mg qd或帕罗西汀20mg qd），短期可辅助劳拉西泮0.5mg prn（不超过2周防依赖）；2.CBT 8-12次：重点处理健康焦虑的认知重构+不确定性耐受训练+减少上网搜索行为（从2h→30min→完全停止）；3.标准8周MBSR课程；4.与内科干预协同（告知患者通过减重戒酒等其异常指标可显著改善）；5.固定睡眠时间（23:00-6:00），睡前2h禁电子设备；6.2周后复评GAD-7/PHQ-9。', '2026-06-05'),
(5, 11,'SCL-90', 88, 'NORMAL', 'SCL-90总分88分（低于全国常模），9个因子分全部<1.5，无任何异常因子。青年阶段正值毕业求职期——在面对找工作和毕业设计的双重压力下仍保持稳定心态，说明心理韧性良好。', '保持积极乐观心态。建议：(1)毕业入职过渡期注意工作-生活平衡；(2)IT行业久坐需结合运动解压；(3)初入职场保持开放心态。每2年做一次心理健康自评。', '2026-07-15'),
(6, 10,'PHQ-9+GAD-7', 8, 'MILD', 'PHQ-9总分5分（亚临床，未达抑郁诊断标准）。GAD-7总分3分（正常）。与糖尿病前期诊断相关的轻度心理负担——对"将来会不会得糖尿病"存在轻度担忧，但未达到焦虑障碍程度。总体心理健康状况良好。', '1.引导正确认知：糖尿病前期是可逆转的（通过减重和生活方式干预可降低58%进展为糖尿病的风险），不是"宣判"；2.运动本身就是良好的抗焦虑"药物"；3.关注正向反馈：体重每减轻1kg、血糖每下降0.1都是进步；4.3-6个月后复评。', '2026-02-20'),
(7, 15,'PHQ-9+GAD-7', 7, 'MILD', 'PHQ-9总分5分（亚临床）：精力不足2分、睡眠1分、兴趣1分。GAD-7总分2分（正常）。轻度情绪低落，主要表现为"老了不中用了"的无力感和退休后社交减少的被动社会退缩。需与COPD慢性低氧导致的精神状态改变相鉴别。', '1.肺功能检查+血气分析以排除COPD低氧导致的精神状态改变；2.加入社区老年活动团体（老年大学、太极班），增加社会参与度；3.每天外出散步与邻居互动；4.成功戒烟本身就是巨大的赋能感；5.戒烟干预1个月后复评（尼古丁戒断症状消退后）。', '2026-04-08');

-- ==============================
-- 13. 干预方案（10条）
-- ==============================
INSERT INTO intervention_plan (id, member_id, plan_name, plan_type, target_goal, start_date, end_date, status, creator_id) VALUES
(1, 1, '赵建国高血压+糖尿病综合管理方案', 'COMPREHENSIVE', '【血压】4周内收缩压降至<140mmHg；【血糖】12周内HbA1c降至<7.0%；【体重】12周内减重3-4kg（BMI<25.5）；【血脂】12周内LDL-C降至<2.6mmol/L。', '2026-03-10', '2026-06-10', 'ACTIVE', 2),
(2, 3, '孙明伟减重逆转脂肪肝方案', 'WEIGHT_LOSS', '【核心目标】6个月减重10-12kg（从91.5kg降至<80kg，BMI<25.2）；【肝功能】12周内ALT降至<50U/L，GGT<60U/L；【血脂】12周内TG降至<2.3mmol/L，24周内TG<1.7；【戒酒】完全戒酒并持续保持；【脂肪肝】24周后腹部超声从中度降至轻度。', '2026-05-20', '2026-11-20', 'ACTIVE', 2),
(3, 4, '李秀英骨质疏松防治方案', 'OSTEOPOROSIS', '【骨密度】12个月后腰椎T值回升至>-1.8，股骨颈T值>-1.5；【维生素D】12周内25-OH维生素D从18.2升至≥30ng/mL；【Hp根除】4周完成四联疗法后确认根除；【跌倒预防】居家环境改造完成。', '2026-03-15', '2026-09-15', 'ACTIVE', 2),
(4, 6, '吴丽华心理健康综合干预方案', 'MENTAL_HEALTH', '【抑郁】8周内PHQ-9从12分降至<8分（临床缓解）；【焦虑】8周内GAD-7从9分降至<5分；【睡眠】4周内入睡时间从>1h缩短至<40min，总睡眠从<5h增至>6h；【社会功能】8周内恢复正常社交和工作功能。', '2026-06-18', '2026-08-18', 'ACTIVE', 2),
(5, 9, '冯志强综合代谢重塑方案', 'COMPREHENSIVE', '【体重】12周减重5-7kg，24周减重12-15kg（目标<83kg）；【血压】4周<150/95，12周<140/90mmHg；【尿酸】8周<420，12周<360μmol/L；【TG】4周<3.5，12周<2.3mmol/L；【LDL-C】12周<2.6mmol/L；【戒酒+戒烟】即刻启动。', '2026-06-05', '2026-12-05', 'ACTIVE', 2),
(6, 10,'陈雪莲糖尿病前期逆转方案', 'DIABETES', '【血糖】12周内FBG从6.8降至<6.1，HbA1c从6.3%降至<6.0%，OGTT 2h<7.8（逆转糖尿病前期）；【体重】12周减重3-5kg（BMI<23.5）；【血压】8周内降至<135/85mmHg；【尿蛋白】12周UACR<30mg/g。', '2026-02-20', '2026-05-20', 'ACTIVE', 4),
(7, 13,'蒋志远降脂减重方案', 'LIPID', '【LDL-C】8周从4.42降至<3.37，12周降至<2.6mmol/L（理想目标）；【体重】12周减重6-8kg（BMI<26.5）；【运动】建立每周≥4次有氧运动习惯。', '2026-05-10', '2026-08-10', 'ACTIVE', 2),
(8, 15,'韩树国戒烟+COPD筛查+降压方案', 'SMOKING', '【戒烟】4周启动计划，8周完全停止吸烟；【筛查】2周内完成肺功能+LDCT；【血压】4周<145/88，12周<140/85mmHg；【运动耐受】12周内从活动后气短改善为可连续步行30min以上。', '2026-04-08', '2026-08-08', 'ACTIVE', 2),
(9, 14,'沈慧芳备孕健康管理方案', 'PREGNANCY', '【营养】4周内转为蛋奶素，确保蛋白质≥60g/日+铁≥20mg/日+维生素B12≥2.4μg/日；【疫苗】8周内完成风疹/水痘/乙肝抗体检测及补种；【牙科】4周内完成口腔检查和必要治疗；【体重】维持健康体重并增加核心肌群力量。', '2026-07-30', '2026-10-30', 'ACTIVE', 2),
(10,7, '郑国强糖尿病年度管理方案', 'DIABETES', '【血糖】HbA1c稳定在<7.0%；【并发症筛查】完成年度筛查（眼底+UACR+eGFR+神经病变+足部检查）；【体重】维持82kg不增加；【运动】制定车内等客时微运动方案（针对出租车司机工作特殊性）。', '2026-07-05', '2027-01-05', 'PENDING', 4);

-- ==============================
-- 14. 人群方案（5条）
-- ==============================
INSERT INTO crowd_program (id, program_name, target_crowd, program_content, frequency, status) VALUES
(1, '企事业单位职工健康促进计划', '20-60岁企事业单位在职职工', '1.每日2次工间操（10:00和15:30，八段锦/广播体操/拉伸训练）；2.季度健康讲座：Q1—心血管与高血压管理，Q2—科学减重与营养，Q3—职场心理健康与压力管理，Q4—体检报告解读与异常指标管理；3.年度健康体检+个人ASCVD风险评估+针对性干预建议；4.建设"健康食堂"（低盐低油菜品标注+热量标识+健康套餐选项）+戒烟限酒倡议；5."健康积分"激励机制：参与体检、讲座、工间操可获积分兑换奖励。', '工间操每日2次；讲座每季度1次；体检每年1次', 'ACTIVE'),
(2, '社区长者健康守护计划', '60岁以上社区居民', '1.社区自助健康监测点（血压计+血糖仪+身高体重秤，异常值自动推送签约家庭医生）；2.每月1次家庭医生巡诊：血压/血糖/体重/用药核查/认知功能MMSE评估+防跌倒家居检查；3.运动团体：太极拳晨练+健步走+广场舞；4.每季度1次用药评估（核查药物相互作用+剂量调整+依从性），提供药品分装盒及用药提醒；5.社区长者食堂低盐低脂高蛋白营养餐（高血压餐/糖尿病餐/普通餐）；6.每月1次集体活动（郊游/手工/书画/棋牌）。', '健康监测每月1次；巡诊每月1次；运动每周≥3次；用药评估每季度1次', 'ACTIVE'),
(3, '中小学生超重/肥胖干预项目', '6-15岁超重及肥胖中小学生', '1.每学期初测量身高体重计算BMI，对超重/肥胖学生发放家长告知书建立健康档案；2.学校食堂减少油炸食品≥50%，增加蔬菜全谷物，取消含糖饮料（替换为白开水/无糖豆浆/纯牛奶）；3.落实"每天校园体育活动1小时"（上午大课间30min+下午体育课或课后活动30min）；4.肥胖学生专项干预：每周2次课后体适能训练（有氧+抗阻+柔韧），家长每月1次线上营养教育+行为指导；5.视力保护：每日眼保健操2次+教室照明达标检查+限制电子屏幕使用时间。', '筛查每学期1次；体适能训练每周2次；家长教育每月1次', 'ACTIVE'),
(4, '职场高压人群心理关爱计划', 'IT/金融/医疗/教育等高压力行业从业人员', '1.季度心理压力在线自评（PSS-10+PHQ-9+GAD-7），结果保密，中重度异常者系统自动建议专业求助；2.标准8周MBSR团体课程（每周2.5h团体课+每日45min家庭练习），认证MBSR教师带领；3.签约EAP服务：每人每年6次免费心理咨询（面对面/视频），48h内预约；4.组织层面：弹性工作制试点+每周三"无会议日下午"+明确"离线权"；5.各部门培养1-2名心理急救员(MHFA)，识别同事心理危机信号并提供初步支持。', '心理评估每季度1次；正念课程每周1次×8周；心理咨询按需使用', 'ACTIVE'),
(5, '企业退休人员健康过渡计划', '即将退休(近6个月)或刚退休(≤1年)的人员', '1.退休前全面健康评估（体检+心理评估+社会支持评估），制定个人退休健康过渡计划；2.每月1次团体辅导（退休身份转变+夫妻关系调适+发现新的生活意义），共6次；3.推荐加入社区运动团体+每年免费参加2期老年大学体育课程；4.健康自管理培训：教会使用血压计/血糖仪、解读体检报告、识别脑卒中/心梗早期预警信号（BEFAST口诀）；5.建立退休人员联络网+每季度线下聚会+鼓励志愿服务（医院导诊/社区健康宣传）。', '退休前评估1次；团体辅导每月1次×6次；聚会每季度1次', 'ACTIVE');

-- ==============================
-- 15. 慢病管理（12条）
-- ==============================
INSERT INTO chronic_disease (id, member_id, disease_name, diagnosis_date, severity, medication, control_status, remark) VALUES
(1, 1, '原发性高血压（1级）', '2020-05-15', 'MILD', '硝苯地平控释片(拜新同) 30mg qd（晨起空腹，整片吞服不可嚼碎）', '未达标（本次148/92mmHg，目标<140/90mmHg，建议加用ARB联合治疗）', '病程6年，2023年因血压控制不佳换用硝苯地平控释片。近1年未调整方案，未规律家庭自测血压。母亲有高血压史。'),
(2, 1, '2型糖尿病', '2022-08-20', 'MILD', '盐酸二甲双胍片(格华止) 0.5g bid（早晚餐后，缓慢加量以减少胃肠道反应）', '未达标（本次HbA1c 6.8%>目标<7.0%，FPG 6.5mmol/L，近期血糖波动大）', '初次诊断时HbA1c 8.2%，单用二甲双胍后降至7.0%左右。近半年饮食松懈、运动减少导致走高。需评估是否联合SGLT-2i（兼有心肾保护获益）。'),
(3, 3, '非酒精性脂肪性肝炎(NASH)', '2024-03-10', 'MODERATE', '水飞蓟宾胶囊(水林佳) 140mg tid + 维生素E软胶囊 400IU bid', '未达标（ALT 78↑、AST 56↑、GGT 128↑↑，腹部超声中度脂肪肝，较2024年诊断时无明显改善）', '确诊2年余，ALT/GGT持续在正常上限1.5-3倍波动。脂肪肝从轻度进展为中度。主因：未坚持戒酒、运动时断时续、饮食控制不严格。警示：10-20%NASH可进展为肝纤维化→肝硬化。'),
(4, 3, '高甘油三酯血症（重度）', '2024-03-10', 'MODERATE', '未规律用药（曾服用非诺贝特200mg qd但自行停药约6个月）', '未达标（TG 3.42↑↑，虽未达急性胰腺炎高风险阈值5.6但已属重度）', '与NASH同时诊断，TG从2.8→3.42呈上升趋势。自行停药是最大问题。需充分教育：①重度高TG的急性胰腺炎风险；②TG与脂肪肝加重的恶性循环。'),
(5, 4, '骨质疏松症（骨量减少期）', '2023-10-12', 'MILD', '阿仑膦酸钠片(福善美) 70mg qw（每周固定一天晨起空腹，满杯水送服，服后保持直立30min）+ 碳酸钙D3片 600mg qd + 维生素D3滴剂 800IU qd', '控制中（T值从-2.4回升至-2.1，治疗有效但仍处于骨量减少范围，需坚持3-5年治疗）', '绝经后骨质流失加速（绝经年龄49岁）。联合治疗T值回升约0.3SD提示有效。本次新增Hp感染诊断，需先根除Hp后再评估钙吸收改善。'),
(6, 7, '2型糖尿病', '2019-03-05', 'MODERATE', '盐酸二甲双胍片 0.5g tid（三餐后）+ 达格列净片(安达唐) 10mg qd（晨起，注意泌尿生殖道感染风险及充足饮水）', '基本达标（最近HbA1c 7.1%略超目标<7.0%，FPG一般6.5-7.5mmol/L范围）', '病程7年，2023年因HbA1c升至7.8%联合达格列净。出租车司机特殊性：(1)不敢多饮水（怕频繁如厕）；(2)三餐时间不固定。需评估是否换用二甲双胍缓释剂型qd方案。'),
(7, 7, '糖尿病性周围神经病变（疑似）', '2024-06-15', 'MILD', '甲钴胺片(弥可保) 0.5mg tid + 依帕司他片 50mg tid', '控制中（双足底麻木感稳定未加重但持续存在，10g单丝检查感觉减退）', '2024年6月因双足底对称性麻木就诊，10g尼龙丝试验阳性（3/10点未感知），振动觉阈值升高。HbA1c需更严格控制以延缓神经病变进展。'),
(8, 9, '高尿酸血症', '2023-06-22', 'MODERATE', '非布司他片(风定宁) 40mg qd（晚餐后，起始期注意痛风发作风险）', '未达标（本次尿酸538μmol/L↑↑，治疗1年效果不理想。原因：饮食未控制+体重持续增加+饮水不足）', '确诊3年，尿酸480-560μmol/L范围波动。2024年曾有1次痛风急性发作（右足第一跖趾关节）。已有颈动脉斑块，尿酸目标应更严格（<300μmol/L）。'),
(9, 9, '颈动脉粥样硬化（斑块形成）', '2026-06-05', 'MODERATE', '阿托伐他汀钙片(立普妥) 20mg qn + 阿司匹林肠溶片(拜阿司匹灵) 100mg qd（一级预防抗血小板）', '新诊断（首次发现右颈总动脉分叉处混合性斑块8.2×2.5mm，狭窄约25%，IMT 1.2mm。治疗即刻启动）', '本次新发现的亚临床动脉粥样硬化证据。是重度肥胖+2级高血压+血脂异常+高尿酸+吸烟+重度饮酒长期综合作用的结果。需集中全部资源进行多重危险因素联合干预，预防脑卒中。'),
(10,10,'原发性高血压（1级）', '2021-11-08', 'MILD', '厄贝沙坦片(安博维) 150mg qd（晨起，ARB兼肾脏保护）', '基本达标（日常家庭自测135-142/82-86mmHg，偶有偏高。目标<140/90，可接受但非理想）', '病程约4.5年，初始155/92mmHg。糖尿病前期+微量白蛋白尿出现后厄贝沙坦肾脏保护价值更凸显。需结合减重和低盐饮食协同降压。'),
(11,10,'糖尿病前期(IFG+IGT)', '2026-02-20', 'MILD', '暂未启动药物治疗，以强化生活方式干预为核心。3个月后评估是否加用二甲双胍（二甲双胍可使糖尿病前期进展为糖尿病的风险降低约31%）', '新诊断（尚处于可逆转窗口期——DPP研究证实强化生活方式干预可使进展为糖尿病的风险降低58%。关键窗口期3-5年，需尽早行动）', '糖尿病前期是中国成人患病率最高的代谢异常之一（约35.2%），约1/3在5年内进展为2型糖尿病。HOMA-IR 4.6示显著胰岛素抵抗。患者主动要求积极干预，配合度高。'),
(12,15,'冠心病（稳定型心绞痛）', '2018-02-14', 'MODERATE', '阿司匹林肠溶片 100mg qd + 阿托伐他汀钙片 20mg qn + 单硝酸异山梨酯缓释片(欣康) 40mg qd', '基本达标（近1年无心绞痛发作，但血压150/90未达标，LDL-C未达冠心病二级预防目标<1.8mmol/L）', '2018年冠脉CTA示LAD中段约40%狭窄。冠心病二级预防LDL-C目标应<1.8（极高危），目前他汀20mg未能达标，需强化至阿托伐他汀40mg或联合依折麦布。戒烟是对预后最大的单个积极影响。');

