-- 17. 科普文章（8篇）
-- ==============================
INSERT INTO knowledge_article (id, title, content, category, author, cover_image, view_count, status) VALUES
(1, '高血压患者家庭自测血压指南', '<h2>为什么要家庭自测血压？</h2><p>诊室血压容易受"白大衣效应"（在医院紧张导致血压偏高）影响。家庭自测能更真实反映日常血压水平，对指导降压治疗非常有价值。</p><h2>如何选择血压计？</h2><ul><li><strong>推荐上臂式电子血压计</strong>：准确度最高，选经过独立临床验证（AAMI/ESH/BHS认证）的产品。欧姆龙、鱼跃等国产品牌性价比高。</li><li><strong>不推荐腕式血压计</strong>：测量误差较大。</li><li><strong>不推荐手指式血压计</strong>：准确度太差，临床不应采用。</li></ul><h2>正确测量方法</h2><ol><li><strong>准备</strong>：测量前30分钟不吸烟、不喝咖啡，排空膀胱。安静休息至少5分钟。</li><li><strong>姿势</strong>：坐直，双脚平放不交叉，手臂放桌面，袖带中心与心脏同一高度（约乳头水平）。</li><li><strong>袖带位置</strong>：下缘距肘窝2-3cm（约两横指），松紧可塞入1-2指。</li><li><strong>测量</strong>：每天早晨（服药前+排尿后）和晚上（睡前）各测2次，间隔1-2分钟。取平均值记录。</li></ol><h2>家庭血压正常值</h2><p>家庭自测血压正常阈值为<strong><135/85mmHg</strong>（低于诊室标准140/90）。</p><h2>血压控制目标</h2><ul><li>一般高血压患者：<140/90mmHg</li><li>合并糖尿病/冠心病/肾病：<130/80mmHg</li><li>老年人(≥65岁)：<150/90mmHg（可耐受者<140/90）</li></ul>', 'CHRONIC', '张伟', '/images/articles/hypertension-monitor.jpg', 2341, 'PUBLISHED'),
(2, '体检报告怎么看？血常规指标全解读', '<h2>血常规——最基础也最重要的检查</h2><p>每次体检必查的血常规，反映身体三大系统：<strong>红细胞系统（氧气运输）、白细胞系统（免疫防御）、血小板系统（止血凝血）</strong>。</p><h2>一、红细胞系统——判断贫血</h2><p>成年男性HGB<130g/L、女性<115g/L即贫血。轻度>90、中度60-90、重度<60g/L。</p><h2>二、白细胞系统——感染的"晴雨表"</h2><p>WBC升高(>9.5×10⁹/L)：最常见于<strong>细菌感染</strong>（扁桃体炎、肺炎、阑尾炎），也见于组织损伤、白血病。</p><p>WBC降低(<3.5×10⁹/L)：常见于<strong>病毒感染</strong>（感冒、流感）、药物影响、自身免疫病。</p><h2>三、血小板系统——止血的"小卫士"</h2><p>PLT<50×10⁹/L：出血风险明显增加（牙龈出血、皮肤瘀斑）。PLT>450×10⁹/L：血栓风险增加。</p><h2>什么情况需要警惕？</h2><ul><li>血红蛋白持续下降+黑便 → 排查消化道出血</li><li>白细胞持续升高+发热+淋巴结肿大 → 排查血液系统疾病</li><li>血小板降低+皮肤瘀斑+牙龈出血 → 排查ITP、DIC等</li></ul>', 'GUIDE', '王强', '/images/articles/blood-test-guide.jpg', 3892, 'PUBLISHED'),
(3, '科学减重：饮食+运动黄金法则', '<h2>减重的本质是能量负平衡——但远不止"管住嘴迈开腿"</h2><p>创造500-750kcal/日热量缺口，每周可减重0.5-1kg。但<strong>单纯靠饿减掉的不仅是脂肪，还有宝贵的肌肉</strong>，基础代谢率下降，反弹风险更高。</p><h2>饮食策略——"三分练，七分吃"</h2><ul><li><strong>蛋白质是关键</strong>：每日1.2-2.0g/kg目标体重，均匀分配三餐（每餐约30-40g蛋白质）。</li><li><strong>膳食纤维≥25-30g/日</strong>：蔬菜500-750g（深色蔬菜占一半）+水果200-350g。</li><li><strong>碳水要"选对"而非"选少"</strong>：全谷物（燕麦、糙米、藜麦）替代精白米面。</li><li><strong>严禁</strong>：含糖饮料、油炸食品、反式脂肪。</li></ul><h2>运动处方——有氧+抗阻最佳组合</h2><ul><li><strong>有氧</strong>：每周150-300分钟中等强度（心率=220-年龄×60-70%）。</li><li><strong>抗阻</strong>：每周2-3次（间隔48h），主要肌群各3组×8-12次。</li><li><strong>NEAT同样重要</strong>：走楼梯、站立办公、步行代替短途驾车——累积起来每天可额外消耗200-500kcal。</li></ul><h2>正确预期</h2><p>健康减重速度是<strong>每月2-4kg</strong>。快速减重（>5kg/月）易导致肌肉流失+代谢下降+反弹。BMI>35者6个月减重10-15%是理想阶段性目标。</p>', 'FITNESS', '陈静', '/images/articles/weight-loss-guide.jpg', 5621, 'PUBLISHED'),
(4, '中医九种体质自测与调理指南', '<h2>了解你的体质——中医体质学说</h2><p>中华中医药学会2009年发布的《中医体质分类与判定》将体质分为1种平和质+8种偏颇体质。知道自己的体质类型，才能进行<strong>个体化</strong>的养生调理。</p><h2>九种体质速查</h2><ul><li><strong>平和质(A型)</strong>：面色红润、精力充沛——保持即可</li><li><strong>气虚质(B型)</strong>：气短乏力、易出汗——益气健脾（黄芪、党参、山药）</li><li><strong>阳虚质(C型)</strong>：怕冷、手足不温——温阳散寒（羊肉、生姜、艾灸）</li><li><strong>阴虚质(D型)</strong>：口燥咽干、手足心热——滋阴降火（银耳、百合、梨）</li><li><strong>痰湿质(E型)</strong>：肥胖、腹部肥满、口黏苔腻——健脾化痰祛湿（薏苡仁、冬瓜）</li><li><strong>湿热质(F型)</strong>：面垢油光、口苦、大便黏滞——清热利湿（绿豆、苦瓜）</li><li><strong>血瘀质(G型)</strong>：肤色晦暗、舌有瘀点——活血化瘀（山楂、黑木耳、三七）</li><li><strong>气郁质(H型)</strong>：神情抑郁、善太息——行气解郁（玫瑰花、佛手）</li><li><strong>特禀质(I型)</strong>：过敏体质——益气固表（黄芪、防风、白术）</li></ul><h2>重要提醒</h2><p>体质不是一成不变的——通过调理，偏颇体质可逐步向平和质转化。调理以3-6个月为一个周期，最好在中医师指导下进行。</p>', 'TCM', '张伟', '/images/articles/tcm-constitution.jpg', 4321, 'PUBLISHED'),
(5, '体检前8小时必读——最完整检前准备清单', '<h2>错误准备可能导致误诊</h2><ul><li><strong>没空腹抽血</strong>→ 血糖、血脂假性升高 → 被误诊为糖尿病/高脂血症</li><li><strong>体检前剧烈运动</strong>→ ALT/CK/肌酐一过性升高 → 被误认为肝损伤/肾损伤</li><li><strong>体检前喝酒</strong>→ GGT/尿酸飙升 → 被误判为酒精性肝损伤</li></ul><h2>完整准备清单</h2><h3>1. 饮食（体检前3天）</h3><p>清淡饮食，避免油腻和饮酒。不要刻意改变饮食习惯（突然"只吃素"反映的不是真实状态）。</p><h3>2. 空腹（前一晚21:00后）</h3><p>禁食8-12小时。可喝少量白开水（<200ml），但不要喝咖啡、茶、含糖饮料。严禁饮酒。</p><h3>3. 药物（体检当天早晨）</h3><p><strong>高血压药</strong>：照常服用（一小口水），突然停用可能导致血压飙升。<strong>糖尿病药/胰岛素</strong>：空腹检查期间暂停，随身携带，检查完及时补用。<strong>正在服用抗凝药/激素/甲状腺素</strong>：请提前告知体检医生。</p><h3>4. 其他</h3><p>穿宽松分体式衣物（方便心电图、超声、采血）。妇科/泌尿系超声需憋尿。女性尿常规尽量避开经期。</p>', 'GUIDE', '王强', '/images/articles/pre-exam-prep.jpg', 8912, 'PUBLISHED'),
(6, '脂肪肝不是"亚健康"——可逆转的肝脏代谢性疾病', '<h2>破除三大误区</h2><p><strong>误区一："脂肪肝只是亚健康"</strong>——错误！10-20%的NAFLD患者会进展为NASH→肝纤维化→肝硬化→肝癌。</p><p><strong>误区二："瘦人不可能有脂肪肝"</strong>——错误！约10-20%的NAFLD患者BMI正常（"瘦人脂肪肝"），亚洲人在较低BMI时更易出现代谢异常。</p><p><strong>误区三："吃点保肝药就行了"</strong>——错误！目前没有任何药物获批为NAFLD一线治疗，<strong>减重是唯一被证实可逆转脂肪肝的干预手段</strong>。</p><h2>脂肪肝逆转路线图</h2><ol><li><strong>减重7-10%</strong>：减重≥7%可显著改善肝脏脂肪变性和炎症（NASH组织学缓解率40-57%），减重≥10%可实现纤维化逆转。</li><li><strong>运动</strong>：有氧（每周150-200min）+抗阻（每周2次）联合效果最优。即使体重未明显下降，运动本身也能减少肝脏脂肪约20-30%。</li><li><strong>饮食</strong>：地中海饮食——高单不饱和脂肪酸（橄榄油）、高ω-3（深海鱼）、高膳食纤维、严格限制果糖（特别是含糖饮料）。</li><li><strong>戒酒</strong>：即使是"少量"也加重肝脏负担。</li><li><strong>咖啡可能有益</strong>：每日2-3杯黑咖啡与肝纤维化风险降低相关（但指的是黑咖啡，不是加糖和奶油的咖啡饮料）。</li></ol>', 'CHRONIC', '张伟', '/images/articles/fatty-liver.jpg', 3456, 'PUBLISHED'),
(7, '科学饮水指南——你真的需要每天八杯水吗？', '<h2>"八杯水"的真相</h2><p>美国国家科学院医学研究所2004年建议更为合理：<strong>男性每日总水摄入约3.7L、女性约2.7L（约80%来自饮料，20%来自食物）</strong>。</p><h2>如何判断是否缺水？</h2><p><strong>看尿色</strong>：淡柠檬水色=水分充足；深黄色=需要补水；澄清无色=可能喝太多。</p><h2>哪些人需特别注意？</h2><ul><li><strong>高尿酸/痛风</strong>：每日饮水≥2000-2500ml，尿量维持≥1500-2000ml/日</li><li><strong>肾结石</strong>：每日饮水≥2500ml，尿量≥2000ml/日</li><li><strong>服用SGLT-2i的糖尿病患者</strong>：需充足饮水降低泌尿生殖道感染风险</li><li><strong>心衰/严重肾功能不全</strong>：需遵医嘱<strong>限制</strong>液体入量（通常每日≤1500ml），不要盲目"多喝水"</li></ul><h2>怎样喝最科学？</h2><p>少量多次优于一次大量。晨起空腹温水200-300ml。饭前30分钟一杯水有助增加饱腹感。睡前1-2h减少饮水以免夜尿影响睡眠。</p>', 'GUIDE', '陈静', '/images/articles/drink-water.jpg', 2345, 'PUBLISHED'),
(8, '戒烟20分钟到20年——身体修复完整时间表', '<h2>戒烟后身体修复时间线</h2><ul><li><strong>20分钟</strong>：心率和血压开始下降</li><li><strong>8小时</strong>：血中一氧化碳浓度减半，血氧水平恢复正常</li><li><strong>24小时</strong>：一氧化碳完全排出，肺开始清除黏液和吸烟残留物</li><li><strong>48小时</strong>：味觉和嗅觉神经末梢开始再生</li><li><strong>2周-3个月</strong>：肺功能改善约30%，血液循环明显改善</li><li><strong>1-9个月</strong>：咳嗽、鼻窦充血和呼吸短促明显减轻；肺纤毛重新生长</li><li><strong>1年</strong>：冠心病风险降至吸烟者的一半</li><li><strong>5年</strong>：脑卒中风险降至与非吸烟者相近</li><li><strong>10年</strong>：肺癌死亡率约为仍在吸烟者的一半</li><li><strong>15年</strong>：冠心病风险降至与非吸烟者相同水平</li></ul><h2>科学戒烟方法</h2><ol><li><strong>设定戒烟日</strong>：选未来2周内的具体日期，"突然停止法"成功率远高于"递减法"。</li><li><strong>尼古丁替代疗法(NRT)</strong>：尼古丁贴片+咀嚼胶双联NRT成功率约27%。</li><li><strong>药物辅助</strong>：伐尼克兰(畅沛)——尼古丁受体部分激动剂；安非他酮——多巴胺/去甲肾上腺素再摄取抑制剂（均需处方）。</li><li><strong>行为干预</strong>：戒烟门诊+CBT，识别触发吸烟的情境并制定替代方案。</li><li><strong>社会支持</strong>：告知亲友，加入戒烟社群。中国戒烟专线：400-888-5531。</li></ol><p><strong>戒烟永远不会太晚</strong>——即使在60岁戒烟，仍能显著延长预期寿命。对于已有冠心病/COPD/肺癌风险的人，戒烟是能做的<strong>对预后最具影响力的单个干预措施</strong>。</p>', 'CHRONIC', '张伟', '/images/articles/quit-smoking.jpg', 4567, 'PUBLISHED');

-- ==============================
-- 18. 运动项目库（10项）
-- ==============================
INSERT INTO exercise_library (id, exercise_name, exercise_type, difficulty, duration, calories_burn, description, video_url, status) VALUES
(1, '健步走', 'AEROBIC', 'EASY', 30, 150, '最安全普适的有氧运动。要领：抬头挺胸收腹，双臂屈肘约90°以肩为轴前后摆动。步频每分钟110-130步。着软底运动鞋在平坦地面进行。适合所有年龄段，特别推荐老年人、超重/肥胖者和慢性病稳定期患者。', '/videos/exercises/walking.mp4', 'ACTIVE'),
(2, '慢跑', 'AEROBIC', 'MEDIUM', 30, 300, '适合有运动基础的人群。正确跑姿：身体稍前倾5-10°，全脚掌或前脚掌着地（避免脚后跟着地的"刹车效应"），步频170-180步/分钟（缩短步幅增加步频可减少膝关节冲击力）。心率控制(220-年龄)×60-75%。跑前热身5分钟+跑后拉伸5-10分钟必不可少。膝关问题者选择塑胶跑道（比水泥地减少约30%冲击力）。', '/videos/exercises/jogging.mp4', 'ACTIVE'),
(3, '游泳(蛙泳)', 'AEROBIC', 'MEDIUM', 45, 400, '全身性低冲击运动，水的浮力支撑约90%体重，关节压力近乎为零。特别推荐给：超重/肥胖(BMI>28)、膝关节/腰椎有伤病、关节炎患者。水温建议26-28℃。不会游泳者可在浅水区做水中行走（消耗热量与游泳接近）。', '/videos/exercises/swimming.mp4', 'ACTIVE'),
(4, '八段锦', 'TRADITIONAL', 'EASY', 20, 80, '国家体育总局推广健身气功，共八式零基础可学。八式与功效：(1)两手托天理三焦——调理气机；(2)左右开弓似射雕——调肺理气；(3)调理脾胃须单举——健脾和胃；(4)五劳七伤往后瞧——疏通颈络；(5)摇头摆尾去心火——清心泻火；(6)两手攀足固肾腰——补肾强腰；(7)攒拳怒目增气力——增强肝气；(8)背后七颠百病消——震动经络。每日晨起练习1-2遍最佳，动作配合呼吸（起吸落呼、开吸合呼）。', '/videos/exercises/baduanjin.mp4', 'ACTIVE'),
(5, '24式简化太极拳', 'TRADITIONAL', 'MEDIUM', 30, 120, '1956年国家体委创编，适合各年龄段。要领：虚灵顶劲、含胸拔背、沉肩坠肘、松腰敛臀。全程重心转移流畅，膝关节微屈不超脚尖（保护膝盖）。初学者可先学前4式（起势→野马分鬃→白鹤亮翅→搂膝拗步），逐步过渡到全套。晨练后微汗即止，不可大汗（传统太极拳主张"微汗养气，大汗伤气"）。', '/videos/exercises/taichi.mp4', 'ACTIVE'),
(6, '哈他瑜伽', 'FLEXIBILITY', 'MEDIUM', 60, 200, '所有现代瑜伽流派的基础，强调体式静态保持+呼吸配合。推荐基础序列：山式→猫牛式→下犬式→战士一→战士二→三角式→桥式→仰卧扭转→摊尸式。注意事项：饱腹后至少间隔2h再练习，经期避免倒置和剧烈扭转体式，高血压避免头部低于心脏的体式。初学者建议跟随老师学习正确顺位。', '/videos/exercises/yoga.mp4', 'ACTIVE'),
(7, '跳绳', 'AEROBIC', 'HARD', 15, 200, '单位时间消耗热量最高——15分钟跳绳≈30分钟慢跑。要领：上臂贴身，前臂外展，用手腕转绳（非整条手臂），双脚并拢膝盖微屈，前脚掌落地快速弹起（离地2-4cm）。着缓冲好的运动鞋在塑胶地面或跳绳垫上进行。禁忌：BMI>28、膝关节/腰椎有伤、严重漏尿者不适合。替代方案：原地高抬腿、开合跳。', '/videos/exercises/jump-rope.mp4', 'ACTIVE'),
(8, '基础力量训练', 'STRENGTH', 'MEDIUM', 45, 350, '针对大肌群的基础抗阻动作（每周2-3次，同一肌群间隔48h）：(1)自重深蹲3组×15-20次；(2)俯卧撑3组×8-15次；(3)弹力带/哑铃划船3组×12-15次；(4)平板支撑3组×30-60秒；(5)臀桥3组×15-20次。要领：发力呼气、还原吸气，全程控制节奏（2秒发力+3秒还原），不借惯性。初学者先掌握自重动作标准姿势再逐步增加负重。每次训练后补充蛋白质20-30g有助肌肉修复。', '/videos/exercises/strength-training.mp4', 'ACTIVE'),
(9, '户外骑行', 'AEROBIC', 'MEDIUM', 60, 500, '低冲击有氧运动极佳选择，膝盖负担小（特别适合膝关节不适者替代跑步）。座高调节：脚踏最低点时膝盖微屈约25-35°。踏频建议80-100转/分钟（用变速器调整阻力而非低速重踩）。必须佩戴头盔，穿着亮色衣物。骑行前后补充水分每小时约500-750ml，长时间骑行(>2h)需补充电解质+碳水化合物。', '/videos/exercises/cycling.mp4', 'ACTIVE'),
(10,'普拉提', 'CORE', 'MEDIUM', 50, 180, '由Joseph Pilates创立的身体控制术，强调核心肌群（腹部+下背+骨盆底+髋部）的控制。核心理念：呼吸（侧后式呼吸）、专注、控制、精准、流畅、中心。推荐基础序列：百次呼吸→卷腹抬起→单腿伸展→双腿伸展→肩桥→侧踢→游泳式→脊柱伸展。特别适合：久坐办公人群（改善体态和腰痛）、产后康复（盆底肌和腹直肌恢复）、舞者和运动员（身体控制力训练）。', '/videos/exercises/pilates.mp4', 'ACTIVE');

-- ==============================
-- 19. 食谱库（8条）
-- ==============================
INSERT INTO recipe_library (id, recipe_name, meal_type, suitable_for, total_calories, cooking_time, difficulty, ingredients, steps, nutrition_info, status) VALUES
(1, '薏仁赤豆茯苓粥', 'BREAKFAST', '痰湿体质/肥胖/水肿/高尿酸', 285, 55, 'EASY', '薏苡仁30g、赤小豆(非红豆)30g、茯苓15g、粳米50g、陈皮3g、冰糖适量(可不加)', '1.薏苡仁、赤小豆提前浸泡至少4h（最好隔夜），茯苓掰小块；2.粳米淘洗干净；3.所有材料（冰糖除外）入砂锅+水约800ml；4.大火煮沸撇去浮沫，转小火慢熬40-50min，期间搅拌2-3次；5.待粥浓稠、赤小豆软烂后加少量冰糖或不加；6.关火焖5分钟。每周3-4次。', '能量285kcal | 蛋白质10.2g | 脂肪2.5g | 碳水56.3g | 膳食纤维5.8g | 钾380mg | 嘌呤含量低 | 薏苡仁含薏苡仁酯(健脾祛湿)、赤小豆含皂苷(利尿消肿)、茯苓多糖(增强免疫)', 'ACTIVE'),
(2, '清蒸鲈鱼配葱姜', 'LUNCH', '高血压/高血脂/减重/术后/孕妇', 348, 25, 'MEDIUM', '鲜鲈鱼1条(约550g)、大葱1根(切丝)、生姜20g(半切片半切丝)、料酒2汤匙、蒸鱼豉油1.5汤匙、花生油1汤匙、红椒丝少许', '1.鲈鱼洗净吸干水分(蒸出不腥的关键)；2.鱼身两面各斜切3道花刀；3.料酒抹鱼身和鱼腹内+铺姜片腌10min；4.蒸盘底垫葱段使鱼离开盘底；5.水开后大火蒸8-10min(鱼眼凸出变白即熟)；6.倒掉盘中蒸出的腥水，去掉蒸过的姜片；7.重新铺新鲜葱姜丝红椒丝；8.烧热1汤匙油至微冒烟，均匀淋在葱姜丝上；9.沿盘边淋蒸鱼豉油。', '能量348kcal | 蛋白质52.3g | 脂肪14.5g(多为不饱和脂肪酸) | 碳水1.2g | ω-3(DHA+EPA约300mg) | 维生素D 5μg | 硒55μg | 极低饱和脂肪 | 淡水鱼中DHA/EPA含量名列前茅', 'ACTIVE'),
(3, '西芹百合炒木耳', 'LUNCH', '高血压/糖尿病/便秘/高血脂', 185, 15, 'EASY', '西芹200g、鲜百合50g、干黑木耳10g、胡萝卜半根、大蒜2瓣、盐1.5g(低盐版)、橄榄油2茶匙、水淀粉少许', '1.干木耳温水泡发30min洗净去蒂撕小朵；2.西芹削去外皮粗纤维斜切段；3.鲜百合掰片，胡萝卜切菱形薄片；4.水开加盐和油，西芹焯水30秒即捞出过凉水(保持爽脆)；5.木耳焯水1min；6.热锅橄榄油炒香蒜末→胡萝卜1min→西芹1min→木耳1min→百合30秒；7.加盐淋水淀粉勾薄芡翻匀出锅。', '能量185kcal | 蛋白质5.2g | 脂肪8.5g(橄榄油不饱和脂肪酸) | 碳水22.3g | 膳食纤维7.2g | 钠约350mg(低盐) | 钾680mg(钾钠比高利降压) | 木耳多糖(降脂抗凝) | 芹菜素(黄酮类降外周血管阻力)', 'ACTIVE'),
(4, '山药红枣排骨汤', 'DINNER', '脾胃虚弱/术后/骨质疏松/儿童', 425, 75, 'MEDIUM', '铁棍山药250g、猪小排350g、红枣8颗(去核)、枸杞15g、生姜4片、料酒2汤匙、盐2g', '1.排骨冷水下锅+2片姜+1汤匙料酒，大火煮沸煮2-3min，撇净浮沫捞出温水冲洗(不要用冷水)；2.山药戴手套削皮切滚刀块，放淡盐水中防氧化；3.排骨+姜片+红枣入砂锅+热水约1500ml；4.大火煮沸转小火炖40min；5.加山药再炖20min至粉糯；6.最后5min加枸杞；7.关火前加盐。汤色乳白山药粉糯排骨酥烂。', '能量425kcal | 蛋白质28.6g | 脂肪22.3g | 碳水28.5g | 钙185mg | 铁4.2mg | 山药黏蛋白(保护胃黏膜) | 红枣多糖(免疫调节) | 胶原蛋白(排骨长时间炖煮释放 利关节皮肤)', 'ACTIVE'),
(5, '百合银耳莲子羹', 'SNACK', '阴虚体质/失眠/皮肤干燥/慢性咽炎', 182, 55, 'EASY', '干银耳15g(约1朵)、去芯莲子30g、干百合20g、红枣5颗、枸杞10g、冰糖15g(减糖版)', '1.银耳冷水泡发3-4h(勿用热水！热水使胶质不易熬出)，去蒂撕小朵(越小越易出胶)；2.莲子去芯与银耳同泡30min；3.干百合温水泡30min，红枣去核；4.银耳+莲子+红枣+冷水约1000ml大火煮沸转小火慢炖40min；5.银耳软糯汤汁黏稠时加百合再炖10-15min；6.加枸杞和冰糖再炖5min；7.关火焖10min。温食或冷藏冰食皆可。', '能量182kcal | 蛋白质4.5g | 脂肪0.8g | 碳水40.2g | 膳食纤维6.5g | 银耳多糖(天然保湿因子 滋阴润肺护肤) | 莲子碱(镇静安神助眠) | 百合秋水仙碱(润肺止咳) | 枸杞多糖(抗氧化保护视网膜)', 'ACTIVE'),
(6, '地中海风味鸡胸藜麦沙拉', 'LUNCH', '减重/健身/糖尿病/高血脂', 385, 30, 'MEDIUM', '鸡胸肉180g、三色藜麦60g(生重)、混合生菜100g、樱桃小番茄10颗(约120g)、黄瓜1根(约150g)、紫洋葱1/4个、腌制橄榄10颗、菲达奶酪30g(可选)、特级初榨橄榄油15ml、新鲜柠檬汁2汤匙、蒜1瓣(压泥)、干燥牛至1/2茶匙、盐和黑胡椒适量', '1.藜麦细网筛冲洗1min去除皂苷(否则苦)，+120ml水+少许盐大火煮沸转小火盖盖煮12-15min至水完全吸收，关火焖5min叉子翻松；2.鸡胸肉拍平至1.5cm厚+盐+黑胡椒+牛至+半份柠檬汁腌15min；3.平底锅中火刷橄榄油，鸡胸每面煎4-5min至金黄全熟，放置5min后斜切片；4.蔬菜洗净切好；5.调汁：橄榄油+柠檬汁+蒜泥+牛至+盐+黑胡椒搅匀乳化；6.大碗中藜麦→蔬菜→鸡胸肉→橄榄→捏碎奶酪→淋调味汁→轻柔翻拌。完美一餐：优质碳水+蛋白质+健康脂肪+大量蔬菜。', '能量385kcal | 蛋白质36.8g | 脂肪16.2g(单不饱和脂肪酸+ω-3) | 碳水28.5g(藜麦低GI) | 膳食纤维7.5g | 铁4.8mg | 镁165mg | 叶酸120μg | 藜麦九种必需氨基酸齐全(完全蛋白质) | 橄榄油富含羟基酪醇(抗炎抗氧化)', 'ACTIVE'),
(7, '南瓜燕麦小米粥', 'BREAKFAST', '糖尿病/减重/便秘/脾胃虚弱', 248, 35, 'EASY', '南瓜200g(约1/4个)、钢切燕麦30g、小米30g、水750ml、枸杞10g', '1.南瓜去皮去籽切2cm小方块（皮可保留需刷净）；2.小米淘洗2遍至水清；3.小米+南瓜+冷水入锅大火煮沸撇去浮沫；4.转小火煮约15min至南瓜变软，勺背压碎部分南瓜（保留部分块状）；5.加燕麦片再煮8-10min，期间搅拌2-3次防粘锅；6.粥浓稠顺滑时加枸杞再煮2min；7.关火焖5min。自带南瓜天然甜味不需加糖。可搭配坚果碎增加风味。', '能量248kcal | 蛋白质7.8g | 脂肪4.5g | 碳水45.2g | 膳食纤维6.8g | β-胡萝卜素约3800μg | 钾485mg | 南瓜多糖(降血糖) | 燕麦β-葡聚糖(可溶性膳食纤维 降低LDL-C) | GI值约45-50(低血糖生成指数 适合糖尿病)', 'ACTIVE'),
(8, '当归黄芪乌鸡汤', 'DINNER', '气血两虚/产后/贫血/月经不调', 395, 105, 'MEDIUM', '乌鸡半只(约500g)、当归片10g、黄芪20g、党参15g、红枣8颗(去核)、枸杞15g、生姜5片、料酒3汤匙、盐2g', '1.乌鸡块冷水下锅+2片姜+2汤匙料酒，大火煮沸煮约3min，撇净浮沫捞出温水冲洗（乌鸡血沫比普通鸡多）；2.当归、黄芪、党参清水快速冲洗（勿长时间浸泡），装入纱布袋包好；3.乌鸡块+药材包+姜片+红枣+料酒1汤匙+热水约1800ml入砂锅；4.大火煮沸转小火盖盖慢炖1.5h；5.捞出药材包丢弃；6.加枸杞再炖5min；7.加盐调味。汤色金黄乌鸡肉酥烂药香温和不冲回甘悠长。', '能量395kcal | 蛋白质42.5g | 脂肪18.6g(乌鸡脂肪远低于普通肉鸡) | 碳水15.2g | 铁8.2mg(血红素铁吸收率约25%远高于植物铁5%) | 锌5.8mg | 当归含阿魏酸(活血补血"血中圣药") | 黄芪含黄芪甲苷IV(益气固表增强免疫) | 乌鸡丰富肌肽和黑色素(抗氧化)', 'ACTIVE');

-- ==============================
-- 20. 疾病库（7种）
-- ==============================
INSERT INTO disease_library (id, disease_name, category, symptoms, causes, treatment, prevention, status) VALUES
(1, '原发性高血压', '心血管疾病', '早期常无症状或仅有头晕、头痛（后枕部胀痛）、心悸、耳鸣。长期高血压可导致：左心室肥厚→心力衰竭、脑卒中（脑出血/脑梗死）、高血压肾病→肾功能衰竭、视网膜病变→视力下降。多数患者在出现并发症前无特异症状，被称为"沉默的杀手"。', '多因素疾病：遗传因素约占40%（有家族史者患病风险增加3-5倍）；环境因素——高钠饮食（中国人日均盐摄入10.5g，远超WHO推荐<5g）、肥胖(BMI≥24)、长期精神应激、缺乏体力活动、过量饮酒（男性>25g酒精/日，女性>15g/日）、年龄增长（动脉弹性减退）。继发性高血压约占5-10%（肾实质性、肾血管性、内分泌性如原发性醛固酮增多症、嗜铬细胞瘤、睡眠呼吸暂停综合征）。', '1.生活方式干预是所有治疗的基础（贯穿全程）；2.药物治疗阶梯式：CCB(氨氯地平/硝苯地平控释片)、ACEI(培哚普利等)/ARB(厄贝沙坦/缬沙坦等)、利尿剂(氢氯噻嗪/吲达帕胺)、β受体阻滞剂(美托洛尔/比索洛尔)；3.通常需要联合用药，单片复方制剂(SPC)提高依从性；4.治疗目标：一般人群<140/90mmHg，合并糖尿病/冠心病/肾病<130/80mmHg，老年人<150/90（可耐受<140/90）。', '1.限盐<5g/日（约一啤酒瓶盖）；2.均衡膳食（增加蔬菜水果、全谷物、低脂乳制品——即DASH饮食模式）；3.每周≥150分钟中等强度有氧运动；4.BMI控制在18.5-23.9；5.戒烟限酒；6.定期监测血压（18岁以上每2年至少测1次血压，40岁以上每年1次，有家族史或高危因素者至少每半年1次）。', 'ACTIVE'),
(2, '2型糖尿病', '内分泌代谢疾病', '典型"三多一少"：多饮、多尿、多食、体重减轻。但约50%患者早期无明显症状，或仅表现为疲乏无力、视力模糊、皮肤瘙痒（尤其是女性外阴瘙痒）、伤口愈合缓慢、反复感染（泌尿系、皮肤）。长期高血糖可导致：糖尿病视网膜病变（致盲主因）、糖尿病肾病（ESRD最常见原因）、糖尿病周围神经病变（双足对称性麻木/疼痛/感觉减退）、糖尿病足（足部溃疡→感染→坏疽→截肢）、心脑血管疾病风险增加2-4倍。', '核心机制：胰岛素抵抗（肌肉/脂肪/肝脏对胰岛素不敏感）+ 胰岛素分泌相对不足（β细胞功能进行性减退）。危险因素：超重/肥胖（BMI≥24风险增加，BMI≥28风险显著增加）、中心性肥胖（腰围男≥90cm/女≥85cm）、缺乏体力活动、不合理膳食（高精制碳水+高饱和脂肪+低膳食纤维）、糖尿病家族史（一级亲属患病者风险增加2-6倍）、年龄≥40岁、巨大儿分娩史或妊娠期糖尿病史、高血压病史。', '1.生活方式干预是基石（贯穿全程）：医学营养治疗(MNT)+运动处方；2.一线药物：二甲双胍（除非禁忌），从0.5g bid起始缓慢加量以减少胃肠道反应；3.二线药物（根据患者特点个体化选择）：SGLT-2i（达格列净/恩格列净——兼有心肾保护+减重获益）、GLP-1RA（利拉鲁肽/司美格鲁肽——兼有减重+心血管保护）、DPP-4i、磺脲类等；4.胰岛素治疗：当口服药+HbA1c仍不达标时启动；5.综合管理目标：HbA1c<7.0%（个体化调整）+血压<130/80mmHg+LDL-C<2.6mmol/L（合并冠心病<1.8）。', '1.保持健康体重（BMI<24），超重/肥胖者减重≥7%可降低糖尿病发生风险58%；2.每周≥150分钟中等强度运动+每周2次抗阻训练；3.均衡膳食（全谷物替代精制碳水、蔬菜≥500g/日、限制含糖饮料、减少红肉和加工肉类）；4.40岁起每年筛查空腹血糖或HbA1c（有糖尿病家族史、超重、高血压等高危因素者建议从35岁或更早开始）；5.糖尿病前期者（IFG/IGT）积极生活方式干预并考虑二甲双胍预防（二甲双胍可降低进展风险31%）。', 'ACTIVE'),
(3, '非酒精性脂肪肝(NAFLD)', '消化系统疾病', '多数患者无症状（约60-80%），常在体检超声或肝功能检查时偶然发现。有症状者常见：右上腹轻度不适或胀痛（肝包膜张力增高所致）、乏力、食欲减退。体检可触及肝大（肝脏增大、质地偏软）。进展为NASH后可有：持续ALT/AST升高（ALT>AST，比值>1具特征性）。晚期肝纤维化/肝硬化表现：肝掌、蜘蛛痣、黄疸、腹水、脾大（门脉高压）。10-20%的NASH患者在10-15年内进展为肝硬化。', '核心机制：肝脏脂质代谢失衡——肝脏脂质摄入/合成超过排出/氧化，导致甘油三酯在肝细胞内异常沉积（肝细胞脂肪变性>5%即可诊断）。胰岛素抵抗是关键驱动因素。危险因素：超重/肥胖（BMI≥24，NAFLD患病率高达60-70%，BMI≥28者高达90%）、中心性肥胖、2型糖尿病/糖尿病前期、高脂血症（特别是高甘油三酯血症）、高果糖摄入（含糖饮料和果汁中的果糖是肝脏脂肪生成的重要底物）、快速减重（反而加重，因脂肪快速动员涌入肝脏）、某些药物（糖皮质激素、他莫昔芬、胺碘酮等）。', '1.减重是唯一被证实可逆转NAFLD的干预：减重≥7%可显著改善肝脏脂肪变性和炎症（NASH组织学缓解率40-57%），减重≥10%可实现纤维化逆转；2.饮食调整：推荐地中海饮食——高单不饱和脂肪酸（橄榄油）+高ω-3（深海鱼）+高膳食纤维+限制果糖（禁含糖饮料）+限制饱和脂肪和精制碳水；3.运动：有氧（每周150-200min）+抗阻（每周2次）联合，即使体重未下降运动本身也能减少肝脏脂肪20-30%；4.药物治疗（辅助）：维生素E 800IU/日（抗氧化，但有一定争议——前列腺癌风险？出血性卒中风险？）、吡格列酮（改善胰岛素抵抗，但注意体重增加和骨折风险）、水飞蓟宾（保肝降酶，证据级别较低）；5.戒酒（即使是"少量"也加重肝脏负担，酒精+脂肪肝=双重打击）；6.咖啡可能有益（每日2-3杯黑咖啡与肝纤维化风险降低相关）。', '1.保持健康体重（BMI<24）和腰围（男<90cm/女<85cm）；2.均衡膳食：多吃蔬菜水果全谷物，少吃高脂高糖加工食品，完全避免含糖饮料；3.每周≥150分钟运动；4.限制饮酒或不饮酒；5.伴有代谢综合征/糖尿病/肥胖者每1-2年腹部超声+肝功能筛查脂肪肝。', 'ACTIVE'),
(4, '高尿酸血症/痛风', '风湿免疫疾病', '高尿酸血症（尿酸>420μmol/L）多数时期无症状。痛风急性发作：常在夜间突然发作，第一跖趾关节最常见（约50-70%），表现为剧烈疼痛（如刀割样/撕裂样）、关节红、肿、发热、活动障碍，疼痛在24小时内达峰，即使不治疗也多在7-14天内自行缓解。慢性期：反复发作→关节破坏变形→痛风石形成（耳廓、鹰嘴、跟腱、指/趾关节等部位皮下硬结，白色尿酸盐结晶）。肾脏损害：尿酸性肾结石（肾绞痛、血尿）、慢性尿酸性肾病。', '核心机制：嘌呤代谢异常导致尿酸生成过多（约占10-20%）和/或肾脏尿酸排泄减少（约占80-90%），血液尿酸浓度超过溶解度（约420μmol/L）时尿酸盐结晶析出，沉积在关节、肾脏等组织中引发炎症反应。危险因素：高嘌呤饮食（动物内脏、贝类海鲜、浓肉汤、红肉）、大量饮酒（啤酒>白酒>红酒，酒精抑制尿酸排泄+增加尿酸生成）、含糖饮料及果糖（果糖代谢消耗ATP→AMP→尿酸+果糖刺激尿酸生成）、肥胖（尤其内脏脂肪）、高血压、肾功能减退、某些药物（噻嗪类利尿剂、小剂量阿司匹林、环孢素等）。遗传因素：家族史阳性者约占10-25%，涉及尿酸转运蛋白基因（SLC2A9/ABCG2等）变异。', '1.急性发作期：快速控制炎症——秋水仙碱（首选，0.5mg tid，注意腹泻不良反应，发作48h内开始效果最好）、NSAIDs（依托考昔/塞来昔布/吲哚美辛，注意胃肠道和肾毒性）、糖皮质激素（用于秋水仙碱和NSAIDs禁忌或不耐受者）；2.缓解期降尿酸治疗：黄嘌呤氧化酶抑制剂——别嘌醇（一线，从50-100mg qd起始缓慢加量，注意超敏反应综合征风险，HLA-B*5801阳性者禁用，汉族携带率约8-10%）或非布司他（别嘌醇不耐受或疗效不佳时）；促进尿酸排泄——苯溴马隆（注意肝毒性，eGFR<20禁用）；3.降尿酸目标：一般<360μmol/L，有痛风石者<300μmol/L；4.碱化尿液（pH 6.2-6.9）：碳酸氢钠/枸橼酸钾；5.每日饮水≥2000-2500ml，尿量维持≥1500-2000ml/日。', '1.低嘌呤饮食（限制动物内脏、贝类海鲜、红肉及浓肉汤，可适量摄入豆制品——已证实植物嘌呤对尿酸影响远小于动物嘌呤）；2.严格限制饮酒（啤酒和白酒尤其明显）；3.避免含糖饮料和果糖摄入（包括果汁和蜂蜜）；4.每日饮水≥2000ml；5.控制体重于健康范围；6.定期监测血尿酸（已有高尿酸血症者每3-6个月1次）。', 'ACTIVE'),
(5, '骨质疏松症', '骨科疾病', '早期常无明显症状，称为"寂静的疾病"。随着病情进展：(1)疼痛——腰背部弥漫性酸痛或钝痛，久坐久站后加重，卧床休息缓解，疼痛沿脊柱向两侧放射；(2)身高缩短——椎体压缩性骨折导致身高逐渐减少（严重者每年缩短1-2cm，椎体压缩总缩短可达10-15cm）；(3)驼背——胸椎压缩性骨折导致胸椎后凸增加（"老妇驼背"）；(4)骨折——最常见部位：椎体（弯腰、咳嗽即可发生）、髋部（股骨颈/粗隆间，致残率和致死率极高，1年内死亡率约20-30%）、腕部（Colles骨折，向前伸手撑地跌倒时发生），轻微外力即可导致骨折（"脆性骨折"）。', '核心机制：骨吸收（破骨细胞）超过骨形成（成骨细胞），骨基质和骨矿物质等比例减少，骨微结构破坏→骨强度下降→骨折风险增加。风险因素分类：(1)不可变：年龄（50岁以上风险显著增加）、女性（绝经后雌激素下降，骨吸收加速）、白种人/亚洲人（骨峰值较低）、髋部骨折家族史、既往脆性骨折史；(2)可变：低体重(BMI<19)、钙摄入不足、维生素D缺乏、缺乏体力活动/卧床制动、吸烟（尼古丁对成骨细胞有直接毒性）、过量饮酒（>2杯/日抑制骨形成）、长期糖皮质激素使用（>3个月相当于泼尼松≥5mg/日——是最常见的继发性骨质疏松原因）、性腺功能减退、吸收不良综合征。(3)继发性原因：原发性甲状旁腺功能亢进、甲状腺功能亢进、多发性骨髓瘤、慢性肝/肾病、类风湿关节炎、糖尿病等。', '1.基础治疗（所有骨质疏松患者都需要）：(1)钙剂——元素钙1000-1200mg/日（饮食+补充剂，优先从饮食获取），常用碳酸钙或枸橼酸钙；(2)维生素D——普通维生素D 800-1200IU/日，使血清25-OH维生素D维持在≥30ng/mL；(3)负重运动（快走/爬楼梯/跳绳）+抗阻训练（弹力带/哑铃），每周≥3次；(4)防跌倒——居家安全评估+平衡训练（太极拳/单腿站立）+视力检查；(5)戒烟限酒。2.抗骨质疏松药物治疗（骨密度T值≤-2.5或已发生脆性骨折）：双膦酸盐类（阿仑膦酸钠70mg qw——一线首选，需空腹满杯水送服并保持直立30min防食管刺激）、地舒单抗（RANKL抑制剂，皮下注射每6个月1次，肾功能不全者安全）、特立帕肽（rhPTH 1-34，促骨形成，用于严重骨质疏松或多椎体骨折）。3.治疗监测：每年或每1-2年复查DXA骨密度，评估疗效。', '1.终身足量钙（青少年建立骨峰值期1000-1300mg/日、成人800-1000mg/日、绝经后及老年1200mg/日）和维生素D（600-800IU/日）摄入；2.每周≥3次负重运动（对骨骼施加机械应力，刺激成骨细胞）+2次抗阻训练；3.戒烟限酒；4.40岁以上女性及50岁以上男性定期评估骨质疏松风险（IOF骨质疏松风险一分钟测试+FRAX骨折风险评估工具），高危者每1-2年DXA骨密度检测；5.绝经后女性评估是否需要激素替代治疗(HRT)（绝经10年内启动对骨骼保护获益最大，但需权衡乳腺癌/血栓风险）。', 'ACTIVE'),
(6, '冠心病（动脉粥样硬化性心脏病）', '心血管疾病', '稳定型心绞痛：胸骨后压榨样/紧缩样/烧灼样不适或疼痛（而非"刺痛"），劳累/情绪激动/寒冷/饱餐后诱发，休息或含服硝酸甘油3-5分钟内缓解，疼痛可放射至左肩/左臂内侧/颈部/下颌/背部（少部分患者仅表现为放射部位症状而胸痛不明显——"异位心绞痛"）。急性冠脉综合征(ACS)：不稳定型心绞痛（胸痛频率/程度/持续时间增加，休息或轻微活动即发作）、非ST段抬高心肌梗死(NSTEMI)、ST段抬高心肌梗死(STEMI——剧烈胸痛>20-30分钟，含服硝酸甘油不缓解，伴大汗、恶心呕吐、濒死感，为心血管急症需立即启动急诊PCI通道）。不典型表现（尤其女性和老年人）：气短、极度疲乏、上腹不适/恶心、背痛（易误诊为消化道疾病或肌肉骨骼问题——"沉默型心肌缺血"）。', '根本病因：冠状动脉粥样硬化——胆固醇在冠脉内膜下沉积→氧化LDL被巨噬细胞吞噬形成泡沫细胞→形成动脉粥样硬化斑块→管腔狭窄→心肌供血不足→心绞痛；斑块破裂→血栓形成→急性血管闭塞→心肌梗死。危险因素（分为可干预和不可干预）：(1)不可干预：年龄（男≥45岁/女≥55岁或早绝经）、性别（绝经前女性有雌激素保护，绝经后风险追赶男性）、冠心病早发家族史（一级亲属男<55岁/女<65岁发病）；(2)可干预：血脂异常（LDL-C升高是动脉粥样硬化的始动和核心因素——"没有胆固醇就没有动脉粥样硬化"）、高血压、糖尿病、吸烟（风险增加2-4倍，包括二手烟）、肥胖(BMI≥28)、缺乏运动、不健康饮食（高饱和脂肪/反式脂肪/高钠/低蔬菜水果/低全谷物）、过量饮酒、心理社会因素（抑郁/焦虑/慢性应激/社会隔离——独立危险因素，相对风险约1.5-2倍）。', '1.生活方式干预贯穿全程：心脏健康饮食（地中海饮食/DASH饮食）、戒烟（最有效的二级预防单措施）、控制体重、规律运动（稳定型心绞痛患者每周150分钟中等强度运动是安全的，PCI/CABG术后应参加心脏康复计划）、心理支持。2.药物治疗（ABCDE原则）：A-抗血小板（阿司匹林/氯吡格雷/替格瑞洛）+ACEI/ARB（抑制RAS系统 保护心血管重构）；B-β受体阻滞剂（降低心肌耗氧量 减少心绞痛发作）+血压控制<130/80mmHg；C-胆固醇管理（他汀为核心，LDL-C目标：稳定型冠心病<1.8mmol/L，ACS<1.4mmol/L或降幅>50%，极高危者可联合依折麦布/PCSK9抑制剂）+戒烟(Cessation)；D-饮食(Diet)+糖尿病管理（HbA1c<7.0%，个体化）；E-运动(Exercise)+教育(Education)。3.血运重建：PCI(经皮冠脉介入治疗——球囊扩张+药物洗脱支架)用于药物控制不佳的稳定型心绞痛或ACS + CABG(冠脉搭桥术——适用于左主干/三支血管/弥漫病变/合并糖尿病等多支病变)。4.心脏康复：运动处方+危险因素管理+心理支持+营养指导+戒烟辅助，完成全程心脏康复可降低心血管死亡率约26%。', '1.从儿童青少年时期开始培养健康生活方式（动脉粥样硬化始于儿童，进展于青年，发病于中老年）；2.健康饮食（增加蔬菜水果、全谷物、鱼、坚果；减少红肉和加工肉类、精制碳水、含糖饮料、盐、反式脂肪）；3.每周≥150分钟中等强度有氧运动+≥2次抗阻训练；4.维持健康体重和腰围；5.完全戒烟和避免二手烟；6.40岁以上成年人定期评估10年ASCVD风险和终身风险（使用中国PAR模型或汇集队列方程），中高危者积极管理血压、血脂、血糖并考虑他汀一级预防。', 'ACTIVE'),
(7, '过敏性鼻炎', '呼吸系统疾病', '四大核心症状：阵发性喷嚏（每次数个至数十个，晨起或接触过敏原后发作）、大量清水样鼻涕（非脓性，不知不觉滴下）、鼻塞（双侧交替性或持续性，夜间加重影响睡眠）、鼻痒（"过敏性敬礼"——反复揉搓鼻尖导致鼻背出现横向皱褶）。伴发症状：眼痒/流泪/眼红（过敏性结膜炎，约50-70%合并）、腭痒/耳痒、嗅觉减退、咳嗽（鼻后滴漏刺激咽喉部）。体征：发作期鼻黏膜苍白水肿（不同于感染性鼻炎的红肿充血）、下鼻甲肿胀、鼻腔水样分泌物、过敏性黑眼圈（allergic shiners——眶下静脉淤血呈暗色）。季节性或常年性发作（取决于过敏原类型）。儿童可影响学习注意力和睡眠质量，成人可影响工作效率。', '过敏原（变应原）刺激鼻黏膜→树突状细胞提呈过敏原→Th2细胞分化→IL-4/IL-13诱导B细胞产生过敏原特异性IgE→IgE与肥大细胞和嗜碱性粒细胞表面FcεRI受体结合→再次接触过敏原时过敏原交叉桥联IgE→肥大细胞脱颗粒释放组胺/白三烯/前列腺素等炎症介质→鼻炎症状（速发相反应，接触后数分钟内发生）→后续嗜酸性粒细胞等炎症细胞浸润→持续鼻塞和鼻高反应性（迟发相反应，接触后4-12小时达峰）。常见过敏原：室内——尘螨（最主要，床垫/枕芯/布艺沙发/地毯中的屋尘螨和粉尘螨）、蟑螂、宠物皮屑（猫>狗）、霉菌孢子。室外——树木花粉（春季，杨/柳/柏/榆等）、草花粉（夏初，豚草/葎草/狗牙根等）、蒿草花粉（秋季，是华北地区最主要的秋季过敏原）。', '1.避开过敏原（最重要最经济的一级干预）：尘螨——使用防螨床品套、55℃以上热水每周清洗床单被套、室内湿度<50%减少尘螨繁殖、移除地毯和布艺家具（改用木/瓷砖地板和皮/木家具）；花粉——花粉季关窗、外出戴口罩（N95优于普通口罩）、回家后洗脸冲洗鼻腔和换衣服；宠物——宠物不进卧室、每周给宠物洗澡、可选HEPA空气净化器；霉菌——清洁室内潮湿区域（浴室、厨房、地下室），修理漏水管道。2.药物治疗（阶梯式）：一线——鼻用糖皮质激素喷雾（丙酸氟替卡松/糠酸莫米松/布地奈德——对四大症状均有效，是目前最有效的单药，起效较慢需持续使用，常用剂量每侧鼻孔1-2喷每日1-2次）；二线辅助——口服/鼻用H1抗组胺药（西替利嗪/氯雷他定/非索非那定——对喷嚏和鼻痒流涕效果好，但对鼻塞效果弱；鼻用剂型——氮䓬斯汀/奥洛他定——起效快15-30min，可按需使用）；白三烯受体拮抗剂（孟鲁司特——对鼻塞效果好，特别适合合并哮喘者）；鼻用色甘酸钠（预防用，运动/接触过敏原前用，安全性极好但效果弱于其他药物）。3.免疫治疗（脱敏治疗，唯一可能改变疾病自然进程的治疗）：皮下免疫治疗(SCIT)——定期皮下注射纯化过敏原提取物，疗程3-5年，有效率约80-85%，但需在医院进行注射后观察至少30min（过敏性休克风险约0.1%）。舌下免疫治疗(SLIT)——粉尘螨滴剂舌下含服，可在家自行使用（首次在医院观察），方便性优于SCIT但有效率略低（约60-70%）。适用于：药物治疗效果不佳或不耐受、希望从根本上改善过敏体质而非仅依赖药物控制的患者。4.鼻腔生理盐水冲洗：每日1-2次（使用洗鼻器或挤压式洗鼻瓶+专用洗鼻盐），机械冲洗过敏原和炎症分泌物，安全无副作用，可单独使用或配合药物治疗。', '1.明确过敏原（皮肤点刺试验或血清特异性IgE检测）并针对性规避；2.家居环境控制：卧室是最关键的空间——防螨床品套+定期高温洗涤+不铺地毯+减少毛绒玩具；3.花粉季戴口罩+回家洗脸冲洗鼻腔+更换外出衣物；4.室内使用HEPA空气净化器（特别是卧室）；5.避免烟草烟雾（吸烟和二手烟会加重鼻黏膜炎症和过敏反应）；6.对于有明确过敏原且常规治疗效果不佳者，可考虑免疫治疗从根本上降低过敏反应。', 'ACTIVE');

-- ==============================
-- 21. 宣教词（9条）
-- ==============================
INSERT INTO education_word (id, term, definition) VALUES
(1, '低盐饮食', '每日食盐摄入量<5g（约等于一啤酒瓶盖或一个半牙膏盖的量），包括食盐、酱油（10ml≈1.5g盐）、味精/鸡精、蚝油等各种调味品中隐藏的盐分。高盐饮食是高血压和脑卒中最重要的可干预危险因素之一。'),
(2, 'BMI(体重指数)', 'BMI = 体重(kg) ÷ 身高²(m²)。中国标准：<18.5偏瘦、18.5-23.9正常、24-27.9超重、≥28肥胖。肥胖是超过200种疾病的独立危险因素或促进因素。BMI不能区分肌肉和脂肪（健美运动员BMI可>28但体脂很低），因此需结合腰围综合判断。'),
(3, 'AEROBIC', '以有氧代谢系统提供能量的持续性、大肌群参与的节律性运动。特点：强度中等（心率=220-年龄×60-75%）、持续时间较长（每次≥30分钟）、可持续进行。常见形式：快走、慢跑、游泳、骑行、跳绳、有氧操。建议每周≥150分钟中等强度或≥75分钟高强度有氧运动。'),
(4, '空腹血糖(FPG)', '禁食8-12小时后（一般前一晚21:00至当日晨起）测得的静脉血浆葡萄糖浓度。正常值3.9-6.1mmol/L。6.1-7.0mmol/L为空腹血糖受损(IFG，糖尿病前期)；≥7.0mmol/L（需重复确认）结合临床症状可诊断糖尿病。血糖受前一晚饮食、睡眠、情绪等因素影响，偶有偏高不足为虑但多次偏高需警惕。'),
(5, '糖化血红蛋白(HbA1c)', '血红蛋白与葡萄糖非酶促结合的产物，反映测定前2-3个月（红细胞的平均寿命约120天）的平均血糖水平——是评估长期血糖控制的"金标准"，不受单次饮食和运动影响（不如空腹血糖波动大）。正常值4.0-6.0%。6.0-6.5%提示糖尿病前期；≥6.5%（需重复确认）可诊断糖尿病。糖尿病患者治疗目标一般<7.0%（个体化调整：年轻/病程短/无并发症者<6.5%，老年/有多种合并症者<8.0%）。'),
(6, '戒烟', '烟草燃烧产生约7000种化学物质，其中至少250种已知对人体有害，69种为已知致癌物。吸烟是心脑血管疾病、COPD、肺癌及其他多种癌症、生殖系统损害、加速衰老（皮肤皱纹/牙齿变黄）的头号可预防死因。任何时候戒烟都不晚——在任何年龄戒烟都能增加预期寿命并改善生活质量。'),
(7, '八段锦', '中国传统导引养生功法，已有800年以上历史。国家体育总局健身气功管理中心2003年组织专家整理推广。共八式："两手托天理三焦、左右开弓似射雕、调理脾胃须单举、五劳七伤往后瞧、摇头摆尾去心火、两手攀足固肾腰、攒拳怒目增气力、背后七颠百病消"。全套练习约12-15分钟，每天早晨练习1-2遍最佳。动作配合腹式呼吸（起吸落呼、开吸合呼、上升吸气下降呼气）。研究表明八段锦可改善平衡能力、降低血压、改善心肺功能、缓解抑郁焦虑、提高睡眠质量。'),
(8, '地中海饮食', '源自20世纪60年代地中海沿岸国家（希腊、意大利南部、西班牙等）的传统饮食模式，被联合国教科文组织列为人类非物质文化遗产。2013年起连续多年蝉联"全球最佳综合饮食"第一名。核心组成：每餐——蔬菜（≥2份）+水果（1-2份）+全谷物（1-2份）+橄榄油（主要烹调用油）+香草和香料（替代盐调味）；每日——坚果/种子（一小把约30g）+低脂乳制品（酸奶/奶酪1-2份）；每周≥2次——鱼/海鲜（ω-3来源）；每周少量——禽肉（白肉）、鸡蛋、豆类；极少——红肉（<每周1-2次）、加工肉类（尽量不吃）、甜点和含糖饮料（仅偶尔）。红葡萄酒可少量（每日≤1杯女性/≤2杯男性，不饮者不必开始，过量抵消所有益处）。已证实对心血管疾病一级和二级预防均有益、延迟认知功能下降、降低总体死亡率、改善代谢综合征。'),
(9, '代谢综合征', '一组同时出现的代谢异常簇集，诊断需满足以下5条中的≥3条：(1)中心性肥胖——腰围男≥90cm/女≥85cm（必备条件之一，中国标准）；(2)高甘油三酯——TG≥1.7mmol/L；(3)低HDL-C——男<1.0mmol/L/女<1.3mmol/L（"好胆固醇"低）；(4)血压升高——SBP≥130或DBP≥85mmHg（或已诊断高血压并服药中）；(5)空腹血糖升高——FPG≥5.6mmol/L（或已诊断2型糖尿病并治疗中）。中国成人代谢综合征患病率约24-33%（即约每3-4个成年人中就有1个）。核心病生理基础：胰岛素抵抗+内脏脂肪过多+慢性低度炎症。代谢综合征患者未来发生CVD和2型糖尿病的风险是正常人的2-3倍和5倍，因此需要积极干预而非视为"亚健康"。');

-- ==============================
-- 22. 宣教内容（5条）
-- ==============================
INSERT INTO education_content (id, title, summary, content, content_type, author, view_count, target_audience, word_id, status) VALUES
(1, '低盐饮食指导手册', '高血压患者如何通过生活方式干预控制血压的完整指南', '<h2>为什么要低盐？</h2><p>我国居民日均食盐摄入量约10.5g，是WHO推荐量(<5g)的2倍以上。高盐饮食是高血压、脑卒中、胃癌、肾脏疾病的重要危险因素。<strong>每人每天减少1g盐，全国每年可减少约10万例脑卒中死亡。</strong></p><h2>盐从哪里来？</h2><ul><li><strong>烹调盐</strong>（炒菜放的盐）——约占总摄入的40-50%</li><li><strong>加工食品</strong>（咸菜/腊肉/火腿/方便面/薯片/酱油/蚝油/味精/豆瓣酱等）——约占总摄入的30-40%</li><li><strong>在外就餐/外卖</strong>——约占总摄入的10-20%</li></ul><h2>如何做到低盐？</h2><ol><li>使用定量盐勺（2g勺或1g勺），炒菜少放盐；</li><li>菜肴出锅前放盐（盐附着于表面，咸味感知更强而实际盐量更少）；</li><li>用香料替代盐——醋、柠檬汁、花椒、八角、姜、蒜、葱、香草等增加风味；</li><li>少食腌制和加工食品——咸菜、腊肉、火腿、罐头、酱料、薯片等；</li><li>学会看食品标签中的"钠"——400mg钠≈1g盐，选择钠含量<120mg/100g的低钠食品；</li><li>减少外卖（外卖口味偏重）和在外就餐，如无法避免可选清蒸/白灼/凉拌等做法并要求"少盐"。</li></ol>', 'ARTICLE', '张伟', 1240, '高血压患者及家属、所有关注健康人群', 1, 'ACTIVE'),
(2, 'BMI自测与体重管理手册', '科学减重的核心原则和实操方法', '<h2>你的BMI是多少？</h2><p>计算公式：体重(kg) ÷ 身高(m) ÷ 身高(m)。例如：体重70kg、身高1.70m的人，BMI = 70÷1.70÷1.70 = 24.2（超重）。</p><table border="1"><tr><th>BMI范围(kg/m²)</th><th>分类</th><th>健康风险</th></tr><tr><td><18.5</td><td>偏瘦</td><td>营养不良、骨质疏松、免疫力下降风险增高</td></tr><tr><td>18.5-23.9</td><td>正常</td><td>理想范围，各类慢性病风险最低</td></tr><tr><td>24-27.9</td><td>超重</td><td>高血压、糖尿病、血脂异常风险开始增加</td></tr><tr><td>28-34.9</td><td>I级肥胖</td><td>代谢综合征、心血管疾病、脂肪肝风险显著增加</td></tr><tr><td>≥35</td><td>II/III级肥胖</td><td>多种严重并发症风险极高，预期寿命显著缩短</td></tr></table><h2>腰围同样重要（中心性肥胖切点）</h2><p>腰围男≥90cm/女≥85cm诊断为中心性肥胖——即使体重和BMI正常但腰围超标，代谢和心血管风险仍显著增加（"正常体重性肥胖"）。正确测量：肚脐上2cm水平绕腰一周，软尺贴皮肤但不压迫，呼气末测量。</p><h2>健康减重原则</h2><ol><li>速度：每月减重2-4kg（每周0.5-1kg），过快减重弊大于利；</li><li>方法：饮食控制+规律运动，双管齐下；</li><li>目标：减重5-10%（例如90kg的人减4.5-9kg），不追求一步到位——减重5%即可获得显著代谢改善（血压↓、血糖↓、血脂改善）；</li><li>维持：减重后维持不反弹同样重要（减重6个月后体重维持是最大挑战）。</li></ol>', 'ARTICLE', '陈静', 980, '所有人群', 2, 'ACTIVE'),
(3, '戒烟指导手册', '戒烟实用方法和应对策略', '<h2>为什么戒烟这么重要？</h2><ul><li>戒烟24小时：心率和血压开始下降至正常水平</li><li>戒烟2周-3个月：肺功能提高约30%，走路更轻松</li><li>戒烟1年：冠心病风险降至吸烟时的一半</li><li>戒烟10年：肺癌风险降至吸烟者的一半以下</li><li>戒烟15年：冠心病风险降至和非吸烟者相同水平</li></ul><h2>戒烟"5A法"</h2><ol><li><strong>Ask（询问）</strong>：坦诚面对自己——每天吸多少支？什么时候最想吸？</li><li><strong>Advise（建议）</strong>：建议自己设定一个具体的"戒烟日"，选在态度比较坚决的时期（如体检后、亲友鼓励时）</li><li><strong>Assess（评估）</strong>：评估尼古丁依赖程度——晨起后多久吸第一支烟？（<30分钟=高度依赖）每天≥20支=高度依赖</li><li><strong>Assist（协助）</strong>：制定戒烟计划——清除家里/办公室/车上所有烟具（打火机/烟灰缸/烟盒）；准备替代品（口香糖/坚果/胡萝卜条/牙签）；告诉亲友你的戒烟决定并寻求支持；启动尼古丁替代疗法（根据依赖程度选择贴片/咀嚼胶/吸入剂）；每天省下的烟钱存起来——1包烟/天×365天≈¥7300-10000+</li><li><strong>Arrange（安排）</strong>：安排随访——戒烟第1周内的吸烟渴求最强烈（戒断症状高峰），提前准备好应对策略（"5D法则"：Delay推迟吸烟念头3-5分钟/Deep breath数次深呼吸/Drink water喝一大杯凉水/Do something做点别的事情分散精力/Discuss找人聊聊自己的感受）；1周后烟瘾大幅减轻，2周后主要是心瘾（情境性渴求）而非生理依赖</li></ol><p>需要帮助？拨打<strong>中国戒烟专线 400-888-5531</strong>（免费，每周一至周五8:00-17:00）或微信搜索"中国戒烟平台"小程序。戒烟门诊可提供伐尼克兰(畅沛)等处方药物辅助，成功率提高2-3倍。</p>', 'ARTICLE', '陈静', 643, '吸烟人群及其家属', 6, 'ACTIVE'),
(4, '地中海饮食入门指南', '地中海饮食的全面介绍及对中国家庭的落地建议', '<h2>什么是地中海饮食？</h2><p>地中海饮食源自1960年代地中海沿岸国家的传统饮食模式，自2013年起连续多年被权威机构评为<strong>"全球最佳综合饮食"第一名</strong>。不是一份死板的"食谱"，而是一种<strong>以植物性食物为主、以橄榄油为核心用油、强调全食物和社交进餐</strong>的饮食生活模式。</p><h2>地中海饮食金字塔（从多到少）</h2><p><strong>每餐吃</strong>：蔬菜（≥2种，生熟搭配）+水果（1-2份）+全谷物（面包/意面/米饭/藜麦）+橄榄油（主要烹调用油）</p><p><strong>每天吃</strong>：坚果和种子（30g，约一小把）+低脂乳制品（酸奶/奶酪1-2份）</p><p><strong>每周≥2次</strong>：鱼和海鲜（富含ω-3的深海鱼如三文鱼/鲭鱼/沙丁鱼优先）</p><p><strong>每周少量</strong>：禽肉（鸡/鸭，白肉）+鸡蛋（2-4个）+豆类（红豆/鹰嘴豆/扁豆等）</p><p><strong>极少</strong>：红肉（牛肉/猪肉/羊肉，<每周1-2次）+加工肉类（火腿/香肠/培根，尽量不吃）+甜点和含糖饮料（仅偶尔）</p><h2>对中国家庭的落地建议</h2><ul><li><strong>油</strong>：以橄榄油（特级初榨，凉拌/低温烹调）和菜籽油（高温烹调）为主，替代猪油/黄油</li><li><strong>蔬菜</strong>：每餐保证有蔬菜（中式炒菜/凉拌/蒸/汤均可），深浅搭配</li><li><strong>主食</strong>：白米饭中混入糙米/燕麦米/小米，逐步过渡到全谷物占主食一半以上</li><li><strong>鱼</strong>：每周≥2次鱼（清蒸/煮汤/烤，不要红烧和油炸破坏ω-3），鲈鱼/鲫鱼/带鱼/黄花鱼/三文鱼均可（淡水鱼也含ω-3，深色鱼肉含量更高）</li><li><strong>肉</strong>：减少红肉频率，用鸡胸肉/去皮鸡腿肉/鱼虾/豆腐替代一部分红肉</li><li><strong>零嘴</strong>：核桃/杏仁/开心果（原味，非盐焗/油炸/糖渍）替代饼干/薯片</li></ul>', 'ARTICLE', '林霞', 2150, '所有人群，特别是高血压/高血脂/糖尿病/肥胖者', 8, 'ACTIVE'),
(5, '糖尿病前期——最好的"后悔药"', '糖尿病前期可逆转——抓住3-5年黄金窗口期', '<h2>什么是糖尿病前期？</h2><p>糖尿病前期是介于正常血糖和糖尿病之间的"灰色地带"——血糖已经超出正常范围，但尚未达到糖尿病的诊断切点。包括：空腹血糖受损(IFG，FPG 6.1-7.0mmol/L）和/或糖耐量减低(IGT，OGTT 2h血糖7.8-11.1mmol/L）。中国成人糖尿病前期患病率约<strong>35.2%</strong>（年龄标化后）——即<strong>每3个成年人中就有1个处于糖尿病前期</strong>，而其中绝大多数人（约70%）并不知道自己处于这个状态。</p><h2>为什么说糖尿病前期是"最好的后悔药"？</h2><p>因为——<strong>糖尿病前期是可逆转的</strong>。它给了你一个珍贵的窗口期（通常3-5年），在此期间积极干预可以"回到健康的队伍"，避免发展为需要终身服药打针的2型糖尿病。</p><h2>数据说话</h2><ul><li><strong>不干预</strong>：每年约5-10%糖尿病前期者进展为糖尿病，5年累积约25-50%</li><li><strong>强化生活方式干预</strong>（减重≥7%+每周≥150分钟运动）：糖尿病发生风险降低<strong>58%</strong>（DPP研究，发表于《新英格兰医学杂志》NEJM 2002）——效果显著优于药物！</li><li><strong>二甲双胍</strong>：降低进展风险<strong>31%</strong>（DPP研究药物组）——不及生活方式干预，但比什么都不做强</li></ul><h2>你应该做什么？</h2><ol><li>减重5-10%（如果你超重/肥胖）——这是最核心的干预，效果远超任何药物</li><li>每周≥150分钟中等强度有氧运动（快走/慢跑/游泳/骑行）+每周2次抗阻训练（增加肌肉量=增加胰岛素敏感性）</li><li>均衡膳食：全谷物替代精制碳水、蔬菜≥500g/日、限制含糖饮料和果汁（含糖饮料是糖尿病前期的"加速器"）</li><li>每3-6个月复查空腹血糖+糖化血红蛋白，评估干预效果</li><li>如果3-6个月强化生活方式干预后血糖仍未改善，请咨询内分泌科是否需要启动二甲双胍治疗</li></ol><p><strong>记住</strong>：糖尿病前期不是"宣判"，而是身体发给你的<strong>"黄色预警信号"</strong>——告诉你要采取行动、改变现状。它是最好的"后悔药"，但窗口期并不长（3-5年），抓住了就是逆转，错过了就只能管理终身。</p>', 'ARTICLE', '张伟', 756, '体检发现血糖偏高（FPG 6.1-7.0或HbA1c 6.0-6.5%）的所有人群', 5, 'ACTIVE');

