INSERT INTO sys_notice (id, user_id, title, content, notice_type, is_read, extra) VALUES
(1, 0, '系统正式上线通知', '传智健康管理系统V2.0正式上线运行。新系统集成了会员管理、体检预约、健康评估、健康干预、知识库和AI健康助手六大模块，支持多角色协同工作。请各位医生、护士在3个工作日内完善个人信息（头像、联系电话、专业特长等）。使用中有任何问题请联系管理员（王强主任）。', 'SYSTEM', 0, '{"priority":"HIGH","expire_days":30}'),
(2, 1, '待处理预约提醒', '您有5条新的体检预约申请等待确认：郑国强(7月5日)、王美玲(7月8日)、褚浩宇(7月15日)、卫晓燕(7月20日)、蒋志远(7月25日)。请在24小时内完成预约确认或改期处理。', 'TASK', 0, '{"priority":"URGENT","action_url":"/appointments/list","action_text":"前往处理"}'),
(3, 2, '体检报告审核通知', '会员赵建国的年度体检报告已于6月28日上传（心脑血管专项套餐），请于48小时内完成审核并出具综合健康建议。另：冯志强的综合体检报告(6月5日)和吴丽华的乳癌筛查报告(6月18日)也已上传待审核。', 'TASK', 0, '{"priority":"URGENT","report_ids":[1,9,6]}'),
(4, 0, '6月份体检质量报告已发布', '2026年6月共完成体检86人次，同比增加15%。平均报告出具时间从3.2天缩短至2.1天。异常检出率前三：血脂异常(38.4%)、超重/肥胖(32.6%)、脂肪肝(25.6%)。详情请查看质控管理-月度报表。', 'SYSTEM', 0, '{"report_month":"2026-06","report_url":"/dashboard/reports/monthly/2026-06"}'),
(5, 3, '新护士培训任务分配', '您被指定为2026年第三季度新入职护士(2名)的临床带教老师。培训周期：2026年7月15日-9月15日。请于7月10日前提交带教计划至护理部。培训内容包括：体检流程规范、静脉采血操作规范、急救技能(CPR+AED)、院感控制、客户沟通技巧。', 'TASK', 0, '{"priority":"MEDIUM","deadline":"2026-07-10"}'),
(6, 4, '体检中心设备维护提醒', '以下设备将于本周五（7月4日）进行季度预防性维护保养：全自动生化分析仪(日立7600)、化学发光免疫分析仪(罗氏E411)、DR X线机(西门子)。请协调相关科室在维护时间段（8:00-12:00）暂停使用受影响的检测项目。', 'TASK', 0, '{"priority":"HIGH","maintenance_date":"2026-07-04"}'),
(8, 2, '健康讲座通知', '7月份院内健康讲座安排：7月12日(周六)14:00-15:30 《高血压患者夏季血压管理》—张伟医生主讲；7月26日(周六)14:00-15:30 《科学减重不反弹》—陈静营养师主讲。地点：门诊楼3层健康宣教室。请各位医生提醒自己的管理对象参加。', 'EVENT', 0, '{"event_date":"2026-07-12","location":"门诊楼3层健康宣教室"}');

