(1, 1, '2026-06-28', '体检', '{"收缩压":148,"舒张压":92,"空腹血糖":6.8,"总胆固醇":5.9,"甘油三酯":2.3,"BMI":26.4,"腰围":98,"心率":78}', '/reports/2026/zhaojianguo.pdf', '血压偏高（SBP>140），建议低盐饮食（<5g/日）+每周5次有氧运动，1个月后复查血压。'),
(2, 2, '2026-06-20', '体检', '{"收缩压":112,"舒张压":70,"空腹血糖":4.9,"总胆固醇":4.5,"甘油三酯":1.1,"BMI":21.3,"腰围":73,"心率":65}', '/reports/2026/qianxiaofang.pdf', '各项指标良好，保持当前健康生活方式即可。'),
(3, 3, '2026-06-05', '体检', '{"收缩压":138,"舒张压":86,"空腹血糖":7.2,"总胆固醇":6.5,"甘油三酯":3.8,"ALT":62,"AST":48,"BMI":28.9,"腰围":105,"脂肪肝":"中度"}', '/reports/2026/sunmingwei.pdf', '中度脂肪肝+血脂异常+空腹血糖受损，需立即进行生活方式干预，3个月后复查。'),
(4, 6, '2026-06-18', '体检', '{"收缩压":118,"舒张压":74,"空腹血糖":5.6,"总胆固醇":5.1,"甘油三酯":1.4,"乳腺彩超":"右乳低回声结节BI-RADS 3类","CA153":18.2,"BMI":24.5,"腰围":82}', '/reports/2026/wulihua.pdf', '乳腺结节BI-RADS 3类（可能良性，恶性可能<2%），建议6个月后复查乳腺彩超。CA153在正常范围内。'),
(5, 1, '2026-07-02', '自测', '{"收缩压":142,"舒张压":88,"心率":76}', NULL, '自测血压仍偏高，继续监测。建议早晚各测一次，记录血压日记。'),
(6, 3, '2026-07-01', '自测', '{"空腹血糖":6.5,"餐后2h血糖":9.8}', NULL, '空腹和餐后血糖仍偏高，需加强饮食控制和运动，建议挂营养科门诊。'),
(7, 9, '2026-06-10', '门诊', '{"收缩压":132,"舒张压":82,"空腹血糖":5.2,"总胆固醇":5.6,"BMI":24.1,"腰围":88}', NULL, '体检异常复查：各项指标较3个月前有所改善（BMI↓1.2，空腹血糖↓0.4），继续坚持当前方案。'),
(8, 12, '2026-06-22', '体检', '{"收缩压":108,"舒张压":68,"空腹血糖":4.6,"总胆固醇":4.2,"BMI":20.8,"腰围":71,"骨密度":"T值-0.8","心率":62}', '/reports/2026/weixiaoyan.pdf', '整体健康良好，骨密度处于正常低值，建议增加钙摄入（牛奶/豆制品）+负重运动。');

